window.VA_CONDS={"class10/biology/circulatory_system":[{"id":"c1","img":"conditions/class10_biology_circulatory_system__1.webp","title":{"en":"Blood flows through the heart","hi":"हृदय से रक्त प्रवाह"},"desc":{"en":"Watch the cells flow. Blue = deoxygenated blood, red = oxygenated blood. The heart is a four-chambered muscular pump.","hi":"रक्त कोशिकाएँ बहती देखिए। नीला = ऑक्सीजन-रहित, लाल = ऑक्सीजन-युक्त; हृदय चार कक्षों वाला पेशीय पंप है।"},"marks":[{"x":47.8,"y":46.2,"en":"Rib cage & breastbone","hi":"पसलियाँ व उरोस्थि"},{"x":55,"y":46.7,"en":"Lungs","hi":"फेफड़े"},{"x":48,"y":26.5,"en":"Windpipe","hi":"श्वासनली"},{"x":52.3,"y":49.1,"en":"Heart (about the size of a fist)","hi":"हृदय (मुट्ठी के बराबर)"}],"src":"ch5/heart3d#0","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c2","img":"conditions/class10_biology_circulatory_system__2.webp","title":{"en":"Four chambers","hi":"चार कक्ष"},"desc":{"en":"Two upper chambers (atria) receive blood; two lower chambers (ventricles) pump it out. The left ventricle has the thickest wall because it pumps blood to the whole body.","hi":"दो ऊपरी कक्ष (अलिंद) रक्त लेते हैं; दो निचले कक्ष (निलय) रक्त बाहर पंप करते हैं। बायाँ निलय सबसे मोटा है क्योंकि वह पूरे शरीर में रक्त भेजता है।"},"marks":[{"x":44.5,"y":51,"en":"Right atrium","hi":"दायाँ अलिंद"},{"x":49,"y":55.3,"en":"Right ventricle","hi":"दायाँ निलय"},{"x":51,"y":49.3,"en":"Left atrium","hi":"बायाँ अलिंद"},{"x":53.8,"y":55.9,"en":"Left ventricle (thickest wall)","hi":"बायाँ निलय (सबसे मोटी भित्ति)"},{"x":49.2,"y":54.3,"en":"Coronary arteries (feed the heart muscle)","hi":"हृदय धमनियाँ"}],"src":"ch5/heart3d#1","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c3","img":"conditions/class10_biology_circulatory_system__3.webp","title":{"en":"Deoxygenated blood enters the right side","hi":"ऑक्सीजन-रहित रक्त दाएँ भाग में"},"desc":{"en":"Blood from the body enters the right atrium through the vena cavae, then passes to the right ventricle. Valves keep the blood flowing in one direction.","hi":"शरीर का रक्त महाशिराओं से दाएँ अलिंद में आता है, फिर दाएँ निलय में जाता है। वाल्व रक्त को एक ही दिशा में बहने देते हैं।"},"marks":[{"x":44.5,"y":51,"en":"Right atrium","hi":"दायाँ अलिंद"},{"x":49,"y":55.3,"en":"Right ventricle","hi":"दायाँ निलय"},{"x":44.8,"y":31.8,"en":"Superior vena cava","hi":"ऊर्ध्व महाशिरा"},{"x":45.5,"y":73.1,"en":"Inferior vena cava","hi":"निम्न महाशिरा"},{"x":54.3,"y":55.5,"en":"Valves (schematic action)","hi":"वाल्व (योजनाबद्ध)"}],"src":"ch5/heart3d#2","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c4","img":"conditions/class10_biology_circulatory_system__4.webp","title":{"en":"To the lungs","hi":"फेफड़ों की ओर"},"desc":{"en":"The right ventricle pumps the blood into the pulmonary artery, which carries it to the lungs.","hi":"दायाँ निलय रक्त को फुफ्फुस धमनी में भेजता है, जो उसे फेफड़ों तक ले जाती है।"},"marks":[{"x":49,"y":55.3,"en":"Right ventricle","hi":"दायाँ निलय"},{"x":57.8,"y":45.2,"en":"Pulmonary artery","hi":"फुफ्फुस धमनी"}],"src":"ch5/heart3d#3","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"}],"class9/biology/respiratory_system":[{"id":"c1","img":"conditions/class9_biology_respiratory_system__1.webp","title":{"en":"The air passage","hi":"वायु का मार्ग"},"desc":{"en":"Air enters through the nose and mouth, passes the throat and the windpipe, and then splits into two bronchi.","hi":"वायु नाक व मुख से गले व श्वासनली में जाकर दो श्वसनियों में बँट जाती है।"},"marks":[{"x":50.1,"y":43.7,"en":"Windpipe (trachea)","hi":"श्वासनली"},{"x":49.3,"y":56.8,"en":"Bronchus","hi":"श्वसनी"},{"x":49.8,"y":17.8,"en":"Epiglottis","hi":"घांटी-ढक्कन"}],"src":"ch5/lungs3d#1","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c2","img":"conditions/class9_biology_respiratory_system__2.webp","title":{"en":"The bronchial tree","hi":"श्वसनी-वृक्ष"},"desc":{"en":"Each bronchus branches into smaller and smaller tubes, like an upside-down tree, and carries air deep into every lobe.","hi":"प्रत्येक श्वसनी छोटी-छोटी नलियों में शाखित होकर हर पाली तक वायु पहुँचाती है — उल्टे पेड़ की तरह।"},"marks":[{"x":49.3,"y":35.9,"en":"Bronchus","hi":"श्वसनी"},{"x":60.6,"y":51.2,"en":"Bronchioles (smaller tubes)","hi":"श्वसनिकाएँ"}],"src":"ch5/lungs3d#2","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c3","img":"conditions/class9_biology_respiratory_system__3.webp","title":{"en":"Alveoli: gas exchange","hi":"एल्वियोलाई: गैस विनिमय"},"desc":{"en":"Each bronchiole ends in a bunch of tiny air sacs (alveoli) wrapped in blood capillaries. Oxygen diffuses into the blood and carbon dioxide diffuses out.","hi":"प्रत्येक श्वसनिका सूक्ष्म वायु-कोष्ठिकाओं (एल्वियोलाई) के गुच्छे में समाप्त होती है, जिनके चारों ओर रक्त केशिकाएँ होती हैं। ऑक्सीजन रक्त में और CO₂ बाहर विसरित होती है।"},"marks":[{"x":60.6,"y":68.7,"en":"Alveoli (air sacs)","hi":"एल्वियोलाई (वायु-कोष्ठिकाएँ)"},{"x":40.8,"y":33.7,"en":"O₂ in → blood, CO₂ out (conceptual)","hi":"O₂ अंदर → रक्त, CO₂ बाहर"}],"src":"ch5/lungs3d#4","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c4","img":"conditions/class9_biology_respiratory_system__4.webp","title":{"en":"Breathing in and out","hi":"श्वास लेना व छोड़ना"},"desc":{"en":"Breathing in: the diaphragm flattens and the ribs move up and out, so the chest gets bigger and air rushes in. Breathing out: the opposite.","hi":"श्वास लेना: डायाफ्राम चपटा और पसलियाँ ऊपर-बाहर जाती हैं, छाती बड़ी होती है और वायु अंदर आती है। श्वास छोड़ना: इसका उल्टा।"},"marks":[{"x":49.2,"y":80.2,"en":"Diaphragm","hi":"डायाफ्राम"},{"x":48.9,"y":48.3,"en":"Rib cage","hi":"पसली-पिंजर"}],"src":"ch5/lungs3d#5","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"}],"class10/biology/excretory_system":[{"id":"c1","img":"conditions/class10_biology_excretory_system__1.webp","title":{"en":"Step 1","hi":"चरण 1"},"desc":{"en":"Filtration — Blood enters the glomerulus under high pressure. Small molecules — water, glucose, salts, urea — are forced into Bowman's capsule. Blood cells and big proteins stay in the blood.","hi":"निस्यंदन — रक्त उच्च दाब पर केशिकागुच्छ में आता है; छोटे अणु — जल, ग्लूकोज़, लवण, यूरिया — बोमन संपुट में निचुड़ते हैं; रक्त कोशिकाएँ व बड़े प्रोटीन रक्त में रहते हैं।"},"marks":[{"x":36.5,"y":45.3,"en":"Bowman's capsule","hi":"बोमन संपुट"},{"x":37.3,"y":43.5,"en":"Glomerulus","hi":"केशिकागुच्छ"},{"x":19.5,"y":28,"en":"Afferent (wide) in","hi":"अभिवाही (चौड़ी) अंदर"},{"x":28.2,"y":67.5,"en":"Efferent (narrow) out","hi":"अपवाही (संकरी) बाहर"},{"x":47.6,"y":32,"en":"Filtrate: water, glucose, salts, urea","hi":"निस्यंद: जल, ग्लूकोज़, लवण, यूरिया"},{"x":26,"y":38.6,"en":"Blood cells & proteins stay","hi":"रक्त कोशिकाएँ व प्रोटीन रुकते"}],"src":"ch5/nephron3d#3"},{"id":"c2","img":"conditions/class10_biology_excretory_system__2.webp","title":{"en":"Step 2","hi":"चरण 2"},"desc":{"en":"Selective reabsorption — Along the proximal tubule the useful substances — all the glucose, amino acids, most salts and much water — are taken back into the capillaries. Urea stays behind.","hi":"चयनात्मक पुनरावशोषण — समीपस्थ नलिका में उपयोगी पदार्थ — सारा ग्लूकोज़, अमीनो अम्ल, अधिकांश लवण व बहुत सा जल — केशिकाओं में लौट जाते हैं; यूरिया पीछे रहता है।"},"marks":[{"x":53.8,"y":50,"en":"Proximal tubule","hi":"समीपस्थ नलिका"},{"x":42.8,"y":50,"en":"Peritubular capillaries","hi":"नलिका-परिवेशी केशिकाएँ"},{"x":38.9,"y":58.2,"en":"Glucose back to blood (100%)","hi":"ग्लूकोज़ रक्त में लौटा (100%)"},{"x":53.8,"y":64.1,"en":"Water & salts back","hi":"जल व लवण वापस"}],"src":"ch5/nephron3d#4"},{"id":"c3","img":"conditions/class10_biology_excretory_system__3.webp","title":{"en":"Step 3","hi":"चरण 3"},"desc":{"en":"Loop of Henle and urine — The loop recovers more water, the distal tubule fine-tunes salts, and the collecting duct saves still more water. What is left — water, urea, extra salts — is urine.","hi":"हेनले पाश व मूत्र — पाश और जल लौटाता है, दूरस्थ नलिका लवण समायोजित करती है, संग्रह नलिका और जल बचाती है; शेष — जल, यूरिया, अतिरिक्त लवण — मूत्र है।"},"marks":[{"x":45.2,"y":87.6,"en":"Loop of Henle","hi":"हेनले पाश"},{"x":55.9,"y":6.1,"en":"Distal tubule","hi":"दूरस्थ नलिका"},{"x":62.4,"y":62,"en":"Collecting duct","hi":"संग्रह नलिका"},{"x":40.9,"y":47,"en":"Urea stays in the tubule","hi":"यूरिया नलिका में रहता"},{"x":54.6,"y":70.8,"en":"Salty medulla (gradient)","hi":"नमकीन मध्यांश (ढाल)"},{"x":62.4,"y":94.9,"en":"Urine: water + urea + salts","hi":"मूत्र: जल + यूरिया + लवण"}],"src":"ch5/nephron3d#5"},{"id":"c4","img":"conditions/class10_biology_excretory_system__4.webp","title":{"en":"Urine's journey","hi":"मूत्र की यात्रा"},"desc":{"en":"Urine collects in the renal pelvis, is pushed down the ureters by peristalsis into the bladder, and is stored. When the bladder is full, sphincters relax and urine is passed out.","hi":"मूत्र श्रोणि में एकत्र होता है, क्रमाकुंचन से मूत्रवाहिनियों में नीचे धकेला जाता है, मूत्राशय में जमा होता है; भर जाने पर अवरोधिनी शिथिल होकर मूत्र निकलता है।"},"marks":[{"x":40,"y":43.6,"en":"Ureter","hi":"मूत्रवाहिनी"},{"x":55.4,"y":78.2,"en":"Urinary bladder","hi":"मूत्राशय"},{"x":50.9,"y":91.6,"en":"Urethra → out","hi":"मूत्रमार्ग → बाहर"}],"src":"ch5/nephron3d#6"},{"id":"c5","img":"conditions/class10_biology_excretory_system__5.webp","title":{"en":"The artificial kidney","hi":"कृत्रिम वृक्क"},"desc":{"en":"When both kidneys fail, urea and extra salts build up in the blood. Haemodialysis does the cleaning outside the body: blood leaves through one needle, is cleaned in the dialyzer and returns through another.","hi":"जब दोनों वृक्क विफल हो जाते हैं, तो रक्त में यूरिया व अतिरिक्त लवण जमा होने लगते हैं। हीमोडायलिसिस सफ़ाई शरीर के बाहर करता है: रक्त एक सुई से निकलता है, डायलाइज़र में साफ़ होता है और दूसरी सुई से लौट आता है।"},"marks":[{"x":51.9,"y":33.2,"en":"Dialysis machine","hi":"डायलिसिस मशीन"},{"x":72.7,"y":40.2,"en":"Dialyzer (artificial kidney)","hi":"डायलाइज़र (कृत्रिम वृक्क)"},{"x":81.5,"y":52.1,"en":"Dialysate supply","hi":"डायलिसिस-द्रव आपूर्ति"}],"src":"ch5/dialysis3d#0"}],"class10/biology/dialysis":[{"id":"c1","img":"conditions/class10_biology_dialysis__1.webp","title":{"en":"Access: the AV fistula","hi":"पहुँच-मार्ग: AV फिस्टुला"},"desc":{"en":"A fistula joins an artery to a vein in the forearm so that the vein becomes thick and strong. Two needles are placed in it: one takes blood out, the other brings it back.","hi":"फिस्टुला बाँह की धमनी को शिरा से जोड़ता है, जिससे शिरा मोटी व मज़बूत हो जाती है। उसमें दो सुइयाँ लगती हैं: एक रक्त निकालती है, दूसरी लौटाती है।"},"marks":[{"x":11.8,"y":52.5,"en":"Patient's forearm","hi":"रोगी की बाँह"},{"x":26.7,"y":41,"en":"AV fistula (artery joined to vein)","hi":"AV फिस्टुला (धमनी + शिरा)"},{"x":43.1,"y":37.3,"en":"Arterial needle — blood OUT","hi":"धमनी-सुई — रक्त बाहर"},{"x":63.7,"y":37.1,"en":"Venous needle — cleaned blood IN","hi":"शिरा-सुई — साफ़ रक्त अंदर"}],"src":"ch5/dialysis3d#1"},{"id":"c2","img":"conditions/class10_biology_dialysis__2.webp","title":{"en":"Blood leaves the body","hi":"रक्त शरीर से बाहर"},"desc":{"en":"The blood pump pushes blood through the arterial line at about 300 mL per minute. A syringe pump adds heparin so the blood does not clot in the circuit.","hi":"रक्त पंप धमनी-लाइन से लगभग 300 mL प्रति मिनट रक्त धकेलता है। सिरिंज पंप हिपेरिन मिलाता है ताकि परिपथ में रक्त न जमे।"},"marks":[{"x":3.7,"y":50.4,"en":"Arterial needle — blood OUT","hi":"धमनी-सुई — रक्त बाहर"},{"x":24.7,"y":30.5,"en":"Arterial blood line","hi":"रक्त-नली (निर्गम)"},{"x":52.9,"y":62,"en":"Blood pump (rollers)","hi":"रक्त पंप (रोलर)"},{"x":79.3,"y":56.7,"en":"Heparin pump (anticlotting)","hi":"हिपेरिन पंप (थक्का-रोधी)"}],"src":"ch5/dialysis3d#2"},{"id":"c3","img":"conditions/class10_biology_dialysis__3.webp","title":{"en":"Inside the dialyzer","hi":"डायलाइज़र के भीतर"},"desc":{"en":"Blood enters at the top and runs down thousands of hollow fibres. Their walls are semi-permeable membranes. The shell is cut open so you can see the fibres.","hi":"रक्त ऊपर से घुसकर हज़ारों खोखले तंतुओं में नीचे बहता है। इनकी दीवारें अर्धपारगम्य झिल्ली हैं। खोल को काटकर तंतु दिखाए गए हैं।"},"marks":[{"x":60.2,"y":29.6,"en":"Dialyzer (artificial kidney)","hi":"डायलाइज़र (कृत्रिम वृक्क)"},{"x":50.2,"y":41,"en":"Hollow fibres (semi-permeable)","hi":"खोखले तंतु (अर्धपारगम्य)"}],"src":"ch5/dialysis3d#3"},{"id":"c4","img":"conditions/class10_biology_dialysis__4.webp","title":{"en":"Diffusion across the membrane","hi":"झिल्ली के आर-पार विसरण"},"desc":{"en":"Magnified view of one fibre wall: urea and extra salts diffuse out through the pores into the dialysing fluid, which has none. Blood cells and big proteins are too large and stay in the blood. There is no reabsorption in dialysis.","hi":"एक तंतु की दीवार का बड़ा दृश्य: यूरिया व अतिरिक्त लवण छिद्रों से निकलकर डायलिसिस-द्रव में विसरित हो जाते हैं, जिसमें ये नहीं होते। रक्त कोशिकाएँ व बड़े प्रोटीन बहुत बड़े हैं और रक्त में ही रहते हैं। डायलिसिस में पुनरावशोषण नहीं होता।"},"marks":[{"x":36.1,"y":50.7,"en":"Pore in the membrane","hi":"झिल्ली का छिद्र"},{"x":64.5,"y":58.2,"en":"Urea & extra salts leave","hi":"यूरिया व अतिरिक्त लवण बाहर"},{"x":29.8,"y":26.9,"en":"Blood cells & proteins stay in","hi":"रक्त कोशिकाएँ व प्रोटीन अंदर"},{"x":72.2,"y":27.1,"en":"Blood side (high urea)","hi":"रक्त की ओर (यूरिया अधिक)"},{"x":72,"y":73.3,"en":"Dialysing fluid side (no urea)","hi":"डायलिसिस-द्रव की ओर (यूरिया नहीं)"}],"src":"ch5/dialysis3d#4"},{"id":"c5","img":"conditions/class10_biology_dialysis__5.webp","title":{"en":"Counter-current flow","hi":"विपरीत-दिशा प्रवाह"},"desc":{"en":"Dialysing fluid enters at the bottom and flows up, opposite to the blood. Meeting fresher fluid all along the way keeps the concentration gradient steep, so more waste is removed.","hi":"डायलिसिस-द्रव नीचे से घुसकर ऊपर बहता है, रक्त के विपरीत। रास्ते भर ताज़ा द्रव मिलने से सांद्रता-ढाल तेज़ बना रहता है, इसलिए अधिक अपशिष्ट निकलता है।"},"marks":[{"x":50,"y":31.3,"en":"Dialyzer (artificial kidney)","hi":"डायलाइज़र (कृत्रिम वृक्क)"},{"x":43.1,"y":8.1,"en":"Blood IN (urea-rich)","hi":"रक्त अंदर (यूरिया अधिक)"},{"x":53.7,"y":68.5,"en":"Fresh dialysing fluid IN","hi":"ताज़ा डायलिसिस-द्रव अंदर"},{"x":53.8,"y":23.7,"en":"Used fluid + urea OUT","hi":"प्रयुक्त द्रव + यूरिया बाहर"},{"x":68.6,"y":54.2,"en":"Dialysate supply","hi":"डायलिसिस-द्रव आपूर्ति"},{"x":77,"y":83,"en":"Drain","hi":"निकास"}],"src":"ch5/dialysis3d#5"},{"id":"c6","img":"conditions/class10_biology_dialysis__6.webp","title":{"en":"Clean blood returns","hi":"साफ़ रक्त की वापसी"},"desc":{"en":"The cleaned blood leaves at the bottom, passes the air trap and goes back to the patient through the venous needle. The blood is warmed and tested for air all the way.","hi":"साफ़ रक्त नीचे से निकलकर एयर-ट्रैप से गुज़रता है और वापसी-सुई से रोगी में लौट जाता है। रास्ते भर रक्त गर्म रखा जाता और हवा की जाँच होती रहती है।"},"marks":[{"x":78.7,"y":70.8,"en":"Blood OUT (cleaned)","hi":"रक्त बाहर (साफ़)"},{"x":61.1,"y":33.3,"en":"Air trap + bubble detector","hi":"एयर-ट्रैप + बुलबुला संसूचक"},{"x":19.3,"y":61.1,"en":"Venous blood line","hi":"रक्त-नली (वापसी)"}],"src":"ch5/dialysis3d#6"},{"id":"c7","img":"conditions/class10_biology_dialysis__7.webp","title":{"en":"Safety, schedule and the cure","hi":"सुरक्षा, समय-सारणी व स्थायी उपाय"},"desc":{"en":"The machine watches pressures, temperature and air. A session lasts about four hours, three times a week, and also removes extra water. A kidney transplant is the permanent solution.","hi":"मशीन दाब, ताप व हवा पर नज़र रखती है। एक सत्र लगभग चार घंटे का होता है, सप्ताह में तीन बार, और अतिरिक्त जल भी निकालता है। वृक्क प्रत्यारोपण स्थायी समाधान है।"},"marks":[{"x":37.4,"y":69.7,"en":"Blood pump (rollers)","hi":"रक्त पंप (रोलर)"},{"x":61.7,"y":65.1,"en":"Heparin pump (anticlotting)","hi":"हिपेरिन पंप (थक्का-रोधी)"},{"x":50,"y":23.2,"en":"Dialysis machine","hi":"डायलिसिस मशीन"},{"x":76.6,"y":78.3,"en":"Air trap + bubble detector","hi":"एयर-ट्रैप + बुलबुला संसूचक"}],"src":"ch5/dialysis3d#7"}],"class10/physics/human_eye_anatomy":[{"id":"c1","img":"conditions/class10_physics_human_eye_anatomy__1.webp","title":{"en":"Cornea: the front window","hi":"कॉर्निया: अगली खिड़की"},"desc":{"en":"Light enters through the transparent cornea. Most of the bending of light happens here. The white sclera forms the rest of the outer coat.","hi":"प्रकाश पारदर्शी कॉर्निया से प्रवेश करता है; अधिकांश अपवर्तन यहीं होता है। सफ़ेद श्वेतपटल शेष बाहरी परत बनाता है।"},"marks":[{"x":47,"y":52.8,"en":"Cornea","hi":"कॉर्निया"},{"x":50.1,"y":50.5,"en":"Sclera","hi":"श्वेतपटल"}],"src":"ch10/eye3d#1","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c2","img":"conditions/class10_physics_human_eye_anatomy__2.webp","title":{"en":"Iris and pupil","hi":"आइरिस और पुतली"},"desc":{"en":"The iris controls how much light passes through the pupil: the pupil gets smaller in bright light and larger in dim light.","hi":"आइरिस पुतली से जाने वाले प्रकाश की मात्रा नियंत्रित करता है: तेज़ प्रकाश में पुतली सिकुड़ती, मंद प्रकाश में फैलती है।"},"marks":[{"x":47.9,"y":52.3,"en":"Iris","hi":"आइरिस"},{"x":48.1,"y":51.9,"en":"Pupil (opening in the iris)","hi":"पुतली"}],"src":"ch10/eye3d#2","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c3","img":"conditions/class10_physics_human_eye_anatomy__3.webp","title":{"en":"Lens: fine focusing","hi":"लेंस: सूक्ष्म फ़ोकस"},"desc":{"en":"The convex lens focuses the light on the retina. Ciliary muscles make it thicker for near objects and thinner for distant ones (accommodation).","hi":"उत्तल लेंस प्रकाश को रेटिना पर फ़ोकस करता है। पास की वस्तु के लिए पक्ष्माभी पेशियाँ उसे मोटा और दूर की वस्तु के लिए पतला करती हैं (समंजन)।"},"marks":[{"x":39.4,"y":50.3,"en":"Lens","hi":"लेंस"},{"x":38.4,"y":50.5,"en":"Ciliary / suspensory fibres","hi":"पक्ष्माभी / निलंबन तंतु"}],"src":"ch10/eye3d#3","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c4","img":"conditions/class10_physics_human_eye_anatomy__4.webp","title":{"en":"Retina: the image forms","hi":"रेटिना: प्रतिबिंब बनता है"},"desc":{"en":"A real, inverted and diminished image forms on the retina. Rods see in dim light; cones see colour in bright light.","hi":"रेटिना पर वास्तविक, उल्टा व छोटा प्रतिबिंब बनता है। शलाकाएँ मंद प्रकाश में व शंकु तेज़ प्रकाश में रंग देखते हैं।"},"marks":[{"x":48.5,"y":50.6,"en":"Retina (image forms here)","hi":"रेटिना (प्रतिबिंब यहाँ)"}],"src":"ch10/eye3d#4","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c5","img":"conditions/class10_physics_human_eye_anatomy__5.webp","title":{"en":"Inside the eye (cut-away)","hi":"आँख के भीतर (अनुप्रस्थ काट)"},"desc":{"en":"Cut open the eye to see all parts together: cornea, aqueous humour, iris, lens, vitreous humour and retina.","hi":"आँख को काटकर सभी भाग एक साथ देखिए: कॉर्निया, नेत्रोद, आइरिस, लेंस, काचाभ द्रव और रेटिना।"},"marks":[{"x":34.9,"y":50.2,"en":"Cornea","hi":"कॉर्निया"},{"x":37.4,"y":50.5,"en":"Iris","hi":"आइरिस"},{"x":39.3,"y":50.3,"en":"Lens","hi":"लेंस"},{"x":48.5,"y":50.6,"en":"Retina (image forms here)","hi":"रेटिना (प्रतिबिंब यहाँ)"},{"x":47.6,"y":50.6,"en":"Vitreous humour","hi":"काचाभ द्रव"},{"x":35.4,"y":50.2,"en":"Aqueous humour","hi":"नेत्रोद"}],"src":"ch10/eye3d#6","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c6","img":"conditions/class10_physics_human_eye_anatomy__6.webp","title":{"en":"Myopia (short-sightedness)","hi":"निकट-दृष्टि दोष"},"desc":{"en":"The image of a far object forms in FRONT of the retina — the eyeball is too long or the lens too strong. Far things look blurred.","hi":"दूर की वस्तु का प्रतिबिंब रेटिना के आगे बनता है — गोलक लंबा या लेंस अधिक शक्तिशाली; दूर की चीज़ें धुँधली।"},"marks":[{"x":47.7,"y":41.7,"en":"Cornea","hi":"कॉर्निया"},{"x":52.1,"y":40.8,"en":"Iris / pupil","hi":"परितारिका / पुतली"},{"x":55,"y":56.7,"en":"Eye lens","hi":"नेत्र लेंस"},{"x":55,"y":40.4,"en":"Ciliary muscles","hi":"पक्ष्माभी पेशियाँ"},{"x":76.9,"y":38.7,"en":"Retina","hi":"दृष्टिपटल"},{"x":85.2,"y":55.4,"en":"Optic nerve","hi":"दृक् तंत्रिका"}],"src":"ch10/eye#1"},{"id":"c7","img":"conditions/class10_physics_human_eye_anatomy__7.webp","title":{"en":"Correct with a concave lens","hi":"अवतल लेंस से सुधार"},"desc":{"en":"A concave (diverging) lens makes the rays diverge slightly so they meet on the retina.","hi":"अवतल (अपसारी) लेंस किरणों को थोड़ा फैलाता है ताकि वे रेटिना पर मिलें।"},"marks":[{"x":47.7,"y":41.7,"en":"Cornea","hi":"कॉर्निया"},{"x":52.1,"y":40.8,"en":"Iris / pupil","hi":"परितारिका / पुतली"},{"x":55,"y":56.7,"en":"Eye lens","hi":"नेत्र लेंस"},{"x":55,"y":40.4,"en":"Ciliary muscles","hi":"पक्ष्माभी पेशियाँ"},{"x":76.9,"y":38.7,"en":"Retina","hi":"दृष्टिपटल"},{"x":85.2,"y":55.4,"en":"Optic nerve","hi":"दृक् तंत्रिका"},{"x":36.1,"y":33.3,"en":"Corrective lens","hi":"संशोधक लेंस"}],"src":"ch10/eye#2"},{"id":"c8","img":"conditions/class10_physics_human_eye_anatomy__8.webp","title":{"en":"Hypermetropia (long-sightedness)","hi":"दूर-दृष्टि दोष"},"desc":{"en":"The image of a near object forms BEHIND the retina — the eyeball is too short. Near things look blurred.","hi":"पास की वस्तु का प्रतिबिंब रेटिना के पीछे बनता है — गोलक छोटा; पास की चीज़ें धुँधली।"},"marks":[{"x":47.7,"y":41.7,"en":"Cornea","hi":"कॉर्निया"},{"x":52.1,"y":40.8,"en":"Iris / pupil","hi":"परितारिका / पुतली"},{"x":55,"y":56.7,"en":"Eye lens","hi":"नेत्र लेंस"},{"x":55,"y":40.4,"en":"Ciliary muscles","hi":"पक्ष्माभी पेशियाँ"},{"x":71.2,"y":38.7,"en":"Retina","hi":"दृष्टिपटल"},{"x":85.2,"y":55.4,"en":"Optic nerve","hi":"दृक् तंत्रिका"}],"src":"ch10/eye#3"},{"id":"c9","img":"conditions/class10_physics_human_eye_anatomy__9.webp","title":{"en":"Correct with a convex lens","hi":"उत्तल लेंस से सुधार"},"desc":{"en":"A convex (converging) lens helps the rays converge earlier so they meet on the retina.","hi":"उत्तल (अभिसारी) लेंस किरणों को पहले मिलाकर रेटिना पर केंद्रित करता है।"},"marks":[{"x":47.7,"y":41.7,"en":"Cornea","hi":"कॉर्निया"},{"x":52.1,"y":40.8,"en":"Iris / pupil","hi":"परितारिका / पुतली"},{"x":55,"y":56.7,"en":"Eye lens","hi":"नेत्र लेंस"},{"x":55,"y":40.4,"en":"Ciliary muscles","hi":"पक्ष्माभी पेशियाँ"},{"x":71.2,"y":38.7,"en":"Retina","hi":"दृष्टिपटल"},{"x":85.2,"y":55.4,"en":"Optic nerve","hi":"दृक् तंत्रिका"},{"x":36.1,"y":33.3,"en":"Corrective lens","hi":"संशोधक लेंस"}],"src":"ch10/eye#4"}],"class10/physics/lens":[{"id":"c1","img":"conditions/class10_physics_lens__1.webp","title":{"en":"Convex lens","hi":"उत्तल लेंस"},"desc":{"en":"Converges rays. Image depends on object distance: real and inverted for u > f, virtual and magnified for u < f (magnifying glass).","hi":"किरणें अभिसारित करता है; u > f पर वास्तविक, उलटा; u < f पर आभासी, बड़ा (आवर्धक लेंस)।"},"marks":[{"x":30.4,"y":40.4,"en":"Object","hi":"वस्तु"},{"x":96.3,"y":54.7,"en":"Image","hi":"प्रतिबिंब"}],"src":"ch9/optics#3"},{"id":"c2","img":"conditions/class10_physics_lens__2.webp","title":{"en":"Concave lens","hi":"अवतल लेंस"},"desc":{"en":"Diverges rays; always a virtual, upright, diminished image (used to correct myopia).","hi":"किरणें अपसारित करता है; सदा आभासी, सीधा, छोटा प्रतिबिंब (निकट-दृष्टि सुधार)।"},"marks":[{"x":30.4,"y":40.4,"en":"Object","hi":"वस्तु"},{"x":61.8,"y":47.6,"en":"Image","hi":"प्रतिबिंब"},{"x":73.4,"y":32.5,"en":"Device","hi":"युक्ति"}],"src":"ch9/optics#4"}],"class10/physics/reflection":[{"id":"c1","img":"conditions/class10_physics_reflection__1.webp","title":{"en":"Concave mirror","hi":"अवतल दर्पण"},"desc":{"en":"Beyond C the image is real, inverted and diminished; between F and the pole it is virtual, upright and magnified (shaving mirror).","hi":"C के पार प्रतिबिंब वास्तविक, उलटा, छोटा; F व ध्रुव के बीच आभासी, सीधा, बड़ा (शेविंग दर्पण)।"},"marks":[{"x":14.6,"y":40.4,"en":"Object","hi":"वस्तु"},{"x":34.7,"y":56,"en":"Image","hi":"प्रतिबिंब"}],"src":"ch9/optics#1"},{"id":"c2","img":"conditions/class10_physics_reflection__2.webp","title":{"en":"Convex mirror","hi":"उत्तल दर्पण"},"desc":{"en":"Always gives a virtual, upright, diminished image — wide field of view, used as a rear-view mirror.","hi":"सदा आभासी, सीधा, छोटा प्रतिबिंब — दृष्टि-क्षेत्र विस्तृत, पश्च-दर्शी दर्पण।"},"marks":[{"x":14.6,"y":40.4,"en":"Object","hi":"वस्तु"},{"x":89.2,"y":47.2,"en":"Image","hi":"प्रतिबिंब"}],"src":"ch9/optics#2"}],"class10/physics/refraction":[{"id":"c1","img":"conditions/class10_physics_refraction__1.webp","title":{"en":"Through a glass slab","hi":"काँच के स्लैब से"},"desc":{"en":"Drag the torch: the ray bends towards the normal on entering and away from it on leaving, emerging parallel to the incident ray but shifted sideways (lateral displacement).","hi":"टॉर्च खींचिए: प्रवेश पर अभिलंब की ओर, निकलते समय दूर मुड़ती है; निर्गत किरण आपतित के समांतर पर पार्श्व में खिसकी (पार्श्व विस्थापन)।"},"marks":[{"x":39.2,"y":22.9,"en":"Incident ray","hi":"आपतित किरण"},{"x":45.9,"y":25.9,"en":"Normal","hi":"अभिलंब"},{"x":48.3,"y":46.9,"en":"Refracted ray (in glass)","hi":"अपवर्तित किरण"},{"x":57.8,"y":70.7,"en":"Emergent ray","hi":"निर्गत किरण"},{"x":56.4,"y":64.1,"en":"Lateral shift","hi":"पार्श्व विस्थापन"}],"src":"ch9/slab#1"},{"id":"c2","img":"conditions/class10_physics_refraction__2.webp","title":{"en":"Water and diamond","hi":"जल व हीरा"},"desc":{"en":"Higher refractive index n = c/v bends light more: water 1.33, glass 1.5, diamond 2.42 (why diamond sparkles).","hi":"अधिक अपवर्तनांक n = c/v पर अधिक मोड़: जल 1.33, काँच 1.5, हीरा 2.42 (इसीलिए हीरा चमकता है)।"},"marks":[{"x":39.2,"y":22.9,"en":"Incident ray","hi":"आपतित किरण"},{"x":45.9,"y":25.9,"en":"Normal","hi":"अभिलंब"},{"x":48.3,"y":46.9,"en":"Refracted ray (in glass)","hi":"अपवर्तित किरण"},{"x":55.7,"y":70.7,"en":"Emergent ray","hi":"निर्गत किरण"},{"x":55,"y":63.2,"en":"Lateral shift","hi":"पार्श्व विस्थापन"}],"src":"ch9/slab#2"},{"id":"c3","img":"conditions/class10_physics_refraction__3.webp","title":{"en":"Normal incidence","hi":"लंबवत आपतन"},"desc":{"en":"At i = 0° the ray goes straight through without bending, whatever the medium.","hi":"i = 0° पर किरण बिना मुड़े सीधी निकल जाती है।"},"marks":[{"x":45.9,"y":18.5,"en":"Incident ray","hi":"आपतित किरण"},{"x":45.9,"y":25.9,"en":"Normal","hi":"अभिलंब"},{"x":48.3,"y":46.9,"en":"Refracted ray (in glass)","hi":"अपवर्तित किरण"},{"x":52.9,"y":70.7,"en":"Emergent ray","hi":"निर्गत किरण"}],"src":"ch9/slab#3"},{"id":"c4","img":"conditions/class10_physics_refraction__4.webp","title":{"en":"Snell's law","hi":"स्नेल का नियम"},"desc":{"en":"sin i / sin r = n (constant for a pair of media). Measure i and r and verify.","hi":"sin i / sin r = n (दो माध्यमों के लिए स्थिर); i व r मापकर जाँचिए।"},"marks":[{"x":45.9,"y":18.5,"en":"Incident ray","hi":"आपतित किरण"},{"x":45.9,"y":25.9,"en":"Normal","hi":"अभिलंब"},{"x":48.3,"y":46.9,"en":"Refracted ray (in glass)","hi":"अपवर्तित किरण"},{"x":52.9,"y":70.7,"en":"Emergent ray","hi":"निर्गत किरण"},{"x":46,"y":68.6,"en":"Lateral shift","hi":"पार्श्व विस्थापन"}],"src":"ch9/slab#4"}],"class10/physics/circuit":[{"id":"c1","img":"conditions/class10_physics_circuit__1.webp","title":{"en":"Series","hi":"श्रेणीक्रम"},"desc":{"en":"Same current through all; voltage divides. R = R₁ + R₂ + R₃ = 6 Ω, so I = 1 A. If one breaks, all stop.","hi":"सभी में समान धारा; विभव बँटता है; R = 1 + 2 + 3 = 6 Ω, I = 1 A; एक टूटे तो सब बंद।"},"marks":[{"x":21.2,"y":42.3,"en":"Battery 6 V","hi":"बैटरी"},{"x":37.8,"y":28.3,"en":"R₁ = 1 Ω","hi":"प्रतिरोधक"},{"x":50,"y":28.3,"en":"R₂ = 2 Ω","hi":"प्रतिरोधक"},{"x":62.2,"y":28.3,"en":"R₃ = 3 Ω","hi":"प्रतिरोधक"}],"src":"ch11/series#1"},{"id":"c2","img":"conditions/class10_physics_circuit__2.webp","title":{"en":"Parallel","hi":"पार्श्वक्रम"},"desc":{"en":"Same voltage across each; current divides. 1/R = 1/1 + 1/2 + 1/3, so R ≈ 0.55 Ω and the total current is large.","hi":"प्रत्येक पर समान वोल्टता, धारा बँटती है; 1/R = 1/1 + 1/2 + 1/3, R ≈ 0.55 Ω; कुल धारा अधिक।"},"marks":[{"x":21.2,"y":42.3,"en":"Battery 6 V","hi":"बैटरी"},{"x":53.5,"y":32.3,"en":"R₁ = 1 Ω","hi":"प्रतिरोधक"},{"x":53.9,"y":46.1,"en":"R₂ = 2 Ω","hi":"प्रतिरोधक"},{"x":54.3,"y":63.2,"en":"R₃ = 3 Ω","hi":"प्रतिरोधक"}],"src":"ch11/series#2"},{"id":"c3","img":"conditions/class10_physics_circuit__3.webp","title":{"en":"Remove one resistor","hi":"एक प्रतिरोधक हटाइए"},"desc":{"en":"In parallel the others keep working — this is how houses are wired. Press Remove R₂.","hi":"पार्श्व में बाकी चलते रहते हैं — घरों में यही जोड़ है; Remove R₂ दबाइए।"},"marks":[{"x":21.2,"y":42.3,"en":"Battery 6 V","hi":"बैटरी"},{"x":53.5,"y":32.3,"en":"R₁ = 1 Ω","hi":"प्रतिरोधक"},{"x":53.9,"y":46.1,"en":"R₂ = 2 Ω","hi":"प्रतिरोधक"},{"x":54.3,"y":63.2,"en":"R₃ = 3 Ω","hi":"प्रतिरोधक"}],"src":"ch11/series#3"}],"class10/physics/magnetic_field_lines":[{"id":"c1","img":"conditions/class10_physics_magnetic_field_lines__1.webp","title":{"en":"Field lines","hi":"क्षेत्र रेखाएँ"},"desc":{"en":"Field lines leave the north pole and enter the south pole outside the magnet; they never cross; crowded lines mean a strong field.","hi":"क्षेत्र रेखाएँ बाहर उत्तरी ध्रुव से निकलकर दक्षिणी में प्रवेश करती हैं; कभी नहीं कटतीं; घनी रेखाएँ = प्रबल क्षेत्र।"},"marks":[{"x":62,"y":35.4,"en":"North pole","hi":"उत्तरी ध्रुव"},{"x":38,"y":35.4,"en":"South pole","hi":"दक्षिणी ध्रुव"},{"x":77,"y":59.8,"en":"Compass (drag me)","hi":"कंपास"}],"src":"ch12/magnet#1"},{"id":"c2","img":"conditions/class10_physics_magnetic_field_lines__2.webp","title":{"en":"The compass","hi":"दिशासूचक"},"desc":{"en":"A compass needle lines up with the field. Drag it around the magnet.","hi":"दिशासूचक सुई क्षेत्र की दिशा में रुकती है; इसे चुंबक के चारों ओर खींचिए।"},"marks":[{"x":62,"y":35.4,"en":"North pole","hi":"उत्तरी ध्रुव"},{"x":38,"y":35.4,"en":"South pole","hi":"दक्षिणी ध्रुव"}],"src":"ch12/magnet#2"},{"id":"c3","img":"conditions/class10_physics_magnetic_field_lines__3.webp","title":{"en":"Flip the magnet","hi":"चुंबक पलटिए"},"desc":{"en":"Reverse the poles: the lines and compass needles reverse direction too.","hi":"ध्रुव उलटिए: रेखाएँ व सुइयाँ भी उलट जाती हैं।"},"marks":[{"x":38,"y":35.4,"en":"North pole","hi":"उत्तरी ध्रुव"},{"x":62,"y":35.4,"en":"South pole","hi":"दक्षिणी ध्रुव"},{"x":45.9,"y":24.1,"en":"Field line: N → S outside, S → N inside","hi":"क्षेत्र रेखा"},{"x":77,"y":59.8,"en":"Compass (drag me)","hi":"कंपास"},{"x":8.8,"y":77.4,"en":"Iron filings — crowded where field is strong","hi":"लौह-चूर्ण"}],"src":"ch12/magnet#3"}],"class10/physics/electromagnet":[{"id":"c1","img":"conditions/class10_physics_electromagnet__1.webp","title":{"en":"Field of a loop","hi":"वृत्ताकार लूप का क्षेत्र"},"desc":{"en":"A current loop gives circular field lines that become straight at the centre; each turn adds to the field.","hi":"धारावाही लूप के क्षेत्र की रेखाएँ केंद्र पर सीधी; हर फेरा क्षेत्र बढ़ाता है।"},"marks":[{"x":50,"y":29.1,"en":"Current-carrying coil","hi":"धारावाही कुंडली"},{"x":52.4,"y":47.9,"en":"Nearly straight at centre","hi":"केंद्र पर सीधी"}],"src":"ch12/solenoid#0"},{"id":"c2","img":"conditions/class10_physics_electromagnet__2.webp","title":{"en":"Solenoid","hi":"परिनालिका"},"desc":{"en":"Many turns close together make a solenoid with a field like a bar magnet: uniform and strong inside.","hi":"अनेक पास-पास फेरे परिनालिका बनाते हैं; क्षेत्र छड़ चुंबक जैसा, भीतर एकसमान व प्रबल।"},"marks":[{"x":50,"y":34.3,"en":"Current-carrying coil","hi":"धारावाही कुंडली"},{"x":59.5,"y":48.7,"en":"Uniform field inside","hi":"एकसमान क्षेत्र"}],"src":"ch12/solenoid#1"},{"id":"c3","img":"conditions/class10_physics_electromagnet__3.webp","title":{"en":"Reverse the current","hi":"धारा उलटिए"},"desc":{"en":"Poles swap: north and south ends reverse.","hi":"ध्रुव बदल जाते हैं — उत्तरी-दक्षिणी सिरे पलटते हैं।"},"marks":[{"x":50,"y":34.3,"en":"Current-carrying coil","hi":"धारावाही कुंडली"},{"x":59.5,"y":48.7,"en":"Uniform field inside","hi":"एकसमान क्षेत्र"}],"src":"ch12/solenoid#2"},{"id":"c4","img":"conditions/class10_physics_electromagnet__4.webp","title":{"en":"Soft-iron core: electromagnet","hi":"नर्म लोहे की क्रोड: विद्युत चुंबक"},"desc":{"en":"A soft-iron core greatly strengthens the field — an electromagnet, magnetic only while current flows (cranes, bells, MRI).","hi":"नर्म लोहे की क्रोड क्षेत्र बहुत बढ़ाती है — विद्युत चुंबक, धारा रहने तक ही चुंबक (क्रेन, घंटी, MRI)।"},"marks":[{"x":50,"y":34.3,"en":"Current-carrying coil","hi":"धारावाही कुंडली"},{"x":59.5,"y":48.7,"en":"Uniform field inside","hi":"एकसमान क्षेत्र"},{"x":52.4,"y":47.9,"en":"Nearly straight at centre","hi":"केंद्र पर सीधी"},{"x":32.1,"y":49.7,"en":"Soft-iron core → electromagnet","hi":"विद्युत चुंबक"}],"src":"ch12/solenoid#3"}],"class10/physics/motor":[{"id":"c1","img":"conditions/class10_physics_motor__1.webp","title":{"en":"Fleming's left-hand rule","hi":"फ़्लेमिंग का बायाँ हाथ नियम"},"desc":{"en":"Left hand: First finger = Field, seCond finger = Current, thuMb = Motion (force). All mutually perpendicular.","hi":"बायाँ हाथ: तर्जनी = क्षेत्र, मध्यमा = धारा, अँगूठा = गति (बल); तीनों परस्पर लंबवत।"},"marks":[{"x":33.5,"y":52,"en":"Aluminium rod","hi":"ऐलुमिनियम छड़"},{"x":47.2,"y":31.8,"en":"Horseshoe magnet","hi":"नाल चुंबक"},{"x":77.3,"y":13.8,"en":"I · B · F (left hand)","hi":"बायाँ हाथ"}],"src":"ch12/flhr#1"},{"id":"c2","img":"conditions/class10_physics_motor__2.webp","title":{"en":"Reverse the current","hi":"धारा उलटिए"},"desc":{"en":"The force reverses: the rod swings the other way.","hi":"बल उलटता है — छड़ दूसरी ओर हिलती है।"},"marks":[{"x":33.6,"y":51.9,"en":"Aluminium rod","hi":"ऐलुमिनियम छड़"},{"x":47.2,"y":31.8,"en":"Horseshoe magnet","hi":"नाल चुंबक"},{"x":77.3,"y":13.8,"en":"I · B · F (left hand)","hi":"बायाँ हाथ"}],"src":"ch12/flhr#2"},{"id":"c3","img":"conditions/class10_physics_motor__3.webp","title":{"en":"Flip the magnet","hi":"चुंबक पलटिए"},"desc":{"en":"Reversing the field also reverses the force.","hi":"क्षेत्र उलटने पर भी बल उलटता है।"},"marks":[{"x":33.6,"y":51.9,"en":"Aluminium rod","hi":"ऐलुमिनियम छड़"},{"x":47.2,"y":31.8,"en":"Horseshoe magnet","hi":"नाल चुंबक"},{"x":77.3,"y":13.8,"en":"I · B · F (left hand)","hi":"बायाँ हाथ"}],"src":"ch12/flhr#3"},{"id":"c4","img":"conditions/class10_physics_motor__4.webp","title":{"en":"Double the current","hi":"धारा दोगुनी"},"desc":{"en":"A stronger current gives a larger force.","hi":"अधिक धारा = अधिक बल।"},"marks":[{"x":29.2,"y":52,"en":"Aluminium rod","hi":"ऐलुमिनियम छड़"},{"x":47.2,"y":31.8,"en":"Horseshoe magnet","hi":"नाल चुंबक"},{"x":77.3,"y":13.8,"en":"I · B · F (left hand)","hi":"बायाँ हाथ"}],"src":"ch12/flhr#4"}],"class10/chemistry/ph":[{"id":"c1","img":"conditions/class10_chemistry_ph__1.webp","title":{"en":"The pH scale","hi":"pH पैमाना"},"desc":{"en":"pH measures how acidic or basic a solution is: 0–6 acid, 7 neutral, 8–14 basic. Each step is a tenfold change in H⁺.","hi":"pH बताता है विलयन कितना अम्लीय/क्षारीय है: 0–6 अम्ल, 7 उदासीन, 8–14 क्षार; हर चरण H⁺ में दस गुना बदलाव।"},"marks":[{"x":25,"y":27.6,"en":"Gastric juice","hi":"जठर रस"},{"x":35,"y":27.6,"en":"Lemon juice","hi":"नींबू रस"},{"x":45,"y":27.6,"en":"Pure water","hi":"शुद्ध जल"},{"x":55,"y":27.6,"en":"Blood","hi":"रक्त"},{"x":65,"y":27.6,"en":"Milk of magnesia","hi":"मिल्क ऑफ मैग्नीशिया"},{"x":75,"y":27.6,"en":"Sodium hydroxide solution","hi":"NaOH विलयन"},{"x":17,"y":78.9,"en":"pH scale","hi":"pH स्केल"}],"src":"ch2/ph#0"},{"id":"c2","img":"conditions/class10_chemistry_ph__2.webp","title":{"en":"Universal indicator","hi":"सार्वत्रिक सूचक"},"desc":{"en":"Add universal indicator to every tube: red/orange acids (1–4), green neutral (7), blue/violet bases (10–14).","hi":"सभी नलियों में सार्वत्रिक सूचक डालिए: लाल/नारंगी अम्ल (1–4), हरा उदासीन (7), नीला/बैंगनी क्षार (10–14)।"},"marks":[{"x":24.9,"y":27.6,"en":"Gastric juice","hi":"जठर रस"},{"x":35,"y":27.6,"en":"Lemon juice","hi":"नींबू रस"},{"x":45,"y":27.6,"en":"Pure water","hi":"शुद्ध जल"},{"x":55,"y":27.6,"en":"Blood","hi":"रक्त"},{"x":65,"y":27.6,"en":"Milk of magnesia","hi":"मिल्क ऑफ मैग्नीशिया"},{"x":75,"y":27.6,"en":"Sodium hydroxide solution","hi":"NaOH विलयन"},{"x":17,"y":78.9,"en":"pH scale","hi":"pH स्केल"}],"src":"ch2/ph#1"},{"id":"c3","img":"conditions/class10_chemistry_ph__3.webp","title":{"en":"Strong and weak","hi":"प्रबल व दुर्बल"},"desc":{"en":"HCl (pH 1) is a strong acid, lemon juice (pH 2) and vinegar (pH 3) weaker; milk is nearly neutral; baking soda (pH 9) and soap are basic; NaOH (pH 14) is a strong base.","hi":"HCl (pH 1) प्रबल अम्ल है; नींबू (pH 2), सिरका (pH 3) दुर्बल; दूध लगभग उदासीन; बेकिंग सोडा (pH 9), साबुन क्षारीय; NaOH (pH 14) प्रबल क्षार।"},"marks":[{"x":24.9,"y":27.6,"en":"Gastric juice","hi":"जठर रस"},{"x":35,"y":27.6,"en":"Lemon juice","hi":"नींबू रस"},{"x":45,"y":27.6,"en":"Pure water","hi":"शुद्ध जल"},{"x":55,"y":27.6,"en":"Blood","hi":"रक्त"},{"x":65,"y":27.6,"en":"Milk of magnesia","hi":"मिल्क ऑफ मैग्नीशिया"},{"x":75,"y":27.6,"en":"Sodium hydroxide solution","hi":"NaOH विलयन"},{"x":17,"y":78.9,"en":"pH scale","hi":"pH स्केल"}],"src":"ch2/ph#2"},{"id":"c4","img":"conditions/class10_chemistry_ph__4.webp","title":{"en":"pH in life","hi":"जीवन में pH"},"desc":{"en":"Blood pH is 7.4; stomach acid pH ≈ 1.5; tooth decay starts below pH 5.5; plants prefer a pH near 6–7 in soil.","hi":"रक्त का pH 7.4; आमाशय अम्ल ≈ 1.5; pH 5.5 से कम पर दाँत सड़ने लगते हैं; पौधे मिट्टी का pH 6–7 पसंद करते हैं।"},"marks":[{"x":24.9,"y":27.6,"en":"Gastric juice","hi":"जठर रस"},{"x":35,"y":27.6,"en":"Lemon juice","hi":"नींबू रस"},{"x":45,"y":27.6,"en":"Pure water","hi":"शुद्ध जल"},{"x":55,"y":27.6,"en":"Blood","hi":"रक्त"},{"x":65,"y":27.6,"en":"Milk of magnesia","hi":"मिल्क ऑफ मैग्नीशिया"},{"x":75,"y":27.6,"en":"Sodium hydroxide solution","hi":"NaOH विलयन"},{"x":17,"y":78.9,"en":"pH scale","hi":"pH स्केल"}],"src":"ch2/ph#3"}],"class10/chemistry/displacement":[{"id":"c1","img":"conditions/class10_chemistry_displacement__1.webp","title":{"en":"Start the reaction","hi":"अभिक्रिया शुरू कीजिए"},"desc":{"en":"Press Start. The blue solution slowly fades and the nail is coated with a reddish-brown layer.","hi":"Start दबाइए: नीला विलयन धीरे-धीरे फीका और कील पर लाल-भूरी परत चढ़ती है।"},"marks":[{"x":37.5,"y":32.6,"en":"Iron nail","hi":"लोहे की कील"},{"x":30.3,"y":64.3,"en":"Copper sulphate (blue)","hi":"कॉपर सल्फेट"},{"x":39.1,"y":59.5,"en":"Copper deposit (brown)","hi":"ताँबे की परत"},{"x":65.3,"y":18.4,"en":"Particle view (zoomed)","hi":"कण-स्तर"}],"src":"ch1/displacement#1"},{"id":"c2","img":"conditions/class10_chemistry_displacement__2.webp","title":{"en":"20 minutes later","hi":"20 मिनट बाद"},"desc":{"en":"Blue Cu²⁺ ions in solution become brown copper metal; green Fe²⁺ ions enter the solution.","hi":"विलयन के नीले Cu²⁺ आयन भूरा ताँबा बनते हैं; हरे Fe²⁺ आयन विलयन में आते हैं।"},"marks":[{"x":37.5,"y":32.6,"en":"Iron nail","hi":"लोहे की कील"},{"x":30.3,"y":64.3,"en":"Iron sulphate (pale green)","hi":"आयरन सल्फेट"},{"x":39.1,"y":59.5,"en":"Copper deposit (brown)","hi":"ताँबे की परत"},{"x":65.3,"y":18.4,"en":"Particle view (zoomed)","hi":"कण-स्तर"}],"src":"ch1/displacement#2"},{"id":"c3","img":"conditions/class10_chemistry_displacement__3.webp","title":{"en":"Particle view","hi":"कण-दृश्य"},"desc":{"en":"Iron atoms lose electrons and go into solution as Fe²⁺; copper ions gain electrons and deposit as atoms — one atom swaps for another.","hi":"लोहे के परमाणु इलेक्ट्रॉन खोकर Fe²⁺ बनते हैं; ताँबे के आयन इलेक्ट्रॉन पाकर परमाणु बनते हैं — एक परमाणु दूसरे का स्थान लेता है।"},"marks":[{"x":37.5,"y":32.6,"en":"Iron nail","hi":"लोहे की कील"},{"x":30.3,"y":64.3,"en":"Copper sulphate (blue)","hi":"कॉपर सल्फेट"},{"x":30.3,"y":64.3,"en":"Iron sulphate (pale green)","hi":"आयरन सल्फेट"},{"x":39.1,"y":59.5,"en":"Copper deposit (brown)","hi":"ताँबे की परत"},{"x":65.3,"y":18.4,"en":"Particle view (zoomed)","hi":"कण-स्तर"}],"src":"ch1/displacement#3"}],"class10/chemistry/neutralisation":[{"id":"c1","img":"conditions/class10_chemistry_neutralisation__1.webp","title":{"en":"Add acid drop by drop","hi":"बूँद-बूँद अम्ल"},"desc":{"en":"Each drop of HCl removes some OH⁻ ions by forming water, and the pink fades.","hi":"HCl की हर बूँद कुछ OH⁻ को जल में बदलती है और गुलाबी रंग फीका होता है।"},"marks":[{"x":28.2,"y":73.9,"en":"NaOH + phenolphthalein","hi":"NaOH + फीनॉल्फ्थेलिन"},{"x":34,"y":17.7,"en":"HCl from burette","hi":"ब्यूरेट से HCl"},{"x":64.6,"y":29.7,"en":"Ions in the flask","hi":"आयन"}],"src":"ch2/neutralisation#1"},{"id":"c2","img":"conditions/class10_chemistry_neutralisation__2.webp","title":{"en":"The end-point","hi":"अंतिम बिंदु"},"desc":{"en":"When the acid has just used up the base, the pink colour disappears — the solution is neutral (pH 7).","hi":"जब अम्ल क्षार को ठीक समाप्त कर दे तो गुलाबी रंग लुप्त होता है — विलयन उदासीन (pH 7)।"},"marks":[{"x":28.2,"y":73.9,"en":"NaOH + phenolphthalein","hi":"NaOH + फीनॉल्फ्थेलिन"},{"x":34,"y":17.7,"en":"HCl from burette","hi":"ब्यूरेट से HCl"},{"x":64.6,"y":29.7,"en":"Ions in the flask","hi":"आयन"}],"src":"ch2/neutralisation#2"},{"id":"c3","img":"conditions/class10_chemistry_neutralisation__3.webp","title":{"en":"In everyday life","hi":"दैनिक जीवन में"},"desc":{"en":"Antacids neutralise stomach acid; toothpaste neutralises mouth acids; lime is added to acidic soil; baking soda soothes a bee sting.","hi":"एंटैसिड पेट का अम्ल, टूथपेस्ट मुँह का अम्ल उदासीन करता है; अम्लीय मिट्टी में चूना डालते हैं; बेकिंग सोडा मधुमक्खी का दंश शांत करता है।"},"marks":[{"x":28.2,"y":73.9,"en":"NaOH + phenolphthalein","hi":"NaOH + फीनॉल्फ्थेलिन"},{"x":34,"y":17.7,"en":"HCl from burette","hi":"ब्यूरेट से HCl"},{"x":64.6,"y":29.7,"en":"Ions in the flask","hi":"आयन"}],"src":"ch2/neutralisation#3"}],"class10/chemistry/reactivity":[{"id":"c1","img":"conditions/class10_chemistry_reactivity__1.webp","title":{"en":"Zn in CuSO₄","hi":"CuSO₄ में Zn"},"desc":{"en":"Pick Zn and CuSO₄, then Dip: zinc is above copper, so it displaces it — copper deposits and the blue colour fades.","hi":"Zn व CuSO₄ चुनकर Dip कीजिए: Zn, Cu से ऊपर है, इसलिए विस्थापित करता है — ताँबा जमता, नीला रंग फीका।"},"marks":[{"x":32.1,"y":26.2,"en":"Reactivity series (most → least)","hi":"सक्रियता श्रेणी"},{"x":80.9,"y":58.1,"en":"Salt solution","hi":"लवण विलयन"},{"x":74.8,"y":32.3,"en":"Metal strip","hi":"धातु की पट्टी"}],"src":"ch3/reactivity#1"},{"id":"c2","img":"conditions/class10_chemistry_reactivity__2.webp","title":{"en":"Fe in CuSO₄","hi":"CuSO₄ में Fe"},"desc":{"en":"Iron is also more reactive than copper, so a reaction occurs.","hi":"लोहा भी ताँबे से अधिक अभिक्रियाशील है, इसलिए अभिक्रिया होती है।"},"marks":[{"x":32.1,"y":26.2,"en":"Reactivity series (most → least)","hi":"सक्रियता श्रेणी"},{"x":80.9,"y":58.1,"en":"Salt solution","hi":"लवण विलयन"},{"x":74.8,"y":32.3,"en":"Metal strip","hi":"धातु की पट्टी"}],"src":"ch3/reactivity#2"},{"id":"c3","img":"conditions/class10_chemistry_reactivity__3.webp","title":{"en":"Cu in FeSO₄: no reaction","hi":"FeSO₄ में Cu: कोई अभिक्रिया नहीं"},"desc":{"en":"Copper is BELOW iron, so it cannot displace iron: nothing happens.","hi":"ताँबा लोहे से नीचे है, इसलिए उसे विस्थापित नहीं कर सकता — कुछ नहीं होता।"},"marks":[{"x":32.1,"y":26.2,"en":"Reactivity series (most → least)","hi":"सक्रियता श्रेणी"},{"x":80.9,"y":58.1,"en":"Salt solution","hi":"लवण विलयन"},{"x":74.8,"y":32.3,"en":"Metal strip","hi":"धातु की पट्टी"}],"src":"ch3/reactivity#3"},{"id":"c4","img":"conditions/class10_chemistry_reactivity__4.webp","title":{"en":"Cu in AgNO₃","hi":"AgNO₃ में Cu"},"desc":{"en":"Copper is above silver: it displaces silver, which forms a shiny deposit; the solution turns blue.","hi":"ताँबा चाँदी से ऊपर है: चाँदी चमकती परत में जमती है, विलयन नीला होता है।"},"marks":[{"x":32.1,"y":26.2,"en":"Reactivity series (most → least)","hi":"सक्रियता श्रेणी"},{"x":80.9,"y":58.1,"en":"Salt solution","hi":"लवण विलयन"},{"x":74.8,"y":32.3,"en":"Metal strip","hi":"धातु की पट्टी"}],"src":"ch3/reactivity#4"}],"class10/biology/genetics_dna":[{"id":"c1","img":"conditions/class10_biology_genetics_dna__1.webp","title":{"en":"Parents: a pure TALL pea plant (TT) is crossed with a pure DWARF pea plant (tt).","hi":"जनक: शुद्ध लंबा (TT) × शुद्ध बौना (tt)।"},"desc":{"en":"Parents: a pure TALL pea plant (TT) is crossed with a pure DWARF pea plant (tt).","hi":"जनक: शुद्ध लंबा (TT) × शुद्ध बौना (tt)।"},"marks":[{"x":32.1,"y":18.8,"en":"Parents (P)","hi":"जनक"}],"src":"ch8/mendel#0"},{"id":"c2","img":"conditions/class10_biology_genetics_dna__2.webp","title":{"en":"F1 generation: ALL plants are tall (Tt). The trait for dwarfness is hidden","hi":"F1: सभी पौधे लंबे (Tt)। लंबापन प्रभावी, बौनापन अप्रभावी।"},"desc":{"en":"tall is DOMINANT, dwarf is RECESSIVE.","hi":"F1: सभी पौधे लंबे (Tt)। लंबापन प्रभावी, बौनापन अप्रभावी।"},"marks":[{"x":14.2,"y":47.6,"en":"F1: all tall (Tt)","hi":"F1 पीढ़ी"}],"src":"ch8/mendel#1"},{"id":"c3","img":"conditions/class10_biology_genetics_dna__3.webp","title":{"en":"F1 plants are self-pollinated. Each makes two kinds of gametes: T and t.","hi":"F1 स्व-परागित: युग्मक T और t।"},"desc":{"en":"F1 plants are self-pollinated. Each makes two kinds of gametes: T and t.","hi":"F1 स्व-परागित: युग्मक T और t।"},"marks":[{"x":14.2,"y":47.6,"en":"F1: all tall (Tt)","hi":"F1 पीढ़ी"},{"x":65,"y":32.8,"en":"Gametes T and t","hi":"युग्मक"}],"src":"ch8/mendel#2"},{"id":"c4","img":"conditions/class10_biology_genetics_dna__4.webp","title":{"en":"F2 generation (Punnett square): TT, Tt, Tt, tt.","hi":"F2: TT, Tt, Tt, tt।"},"desc":{"en":"F2 generation (Punnett square): TT, Tt, Tt, tt.","hi":"F2: TT, Tt, Tt, tt।"},"marks":[{"x":86,"y":49.4,"en":"F2: 3 tall : 1 dwarf","hi":"F2 पीढ़ी"}],"src":"ch8/mendel#3"},{"id":"c5","img":"conditions/class10_biology_genetics_dna__5.webp","title":{"en":"Result: 3 tall : 1 dwarf (phenotype). Genotype ratio 1 TT : 2 Tt : 1 tt. Dwarfness reappears in F2.","hi":"परिणाम: 3 लंबे : 1 बौना; जीनोटाइप 1:2:1।"},"desc":{"en":"Result: 3 tall : 1 dwarf (phenotype). Genotype ratio 1 TT : 2 Tt : 1 tt. Dwarfness reappears in F2.","hi":"परिणाम: 3 लंबे : 1 बौना; जीनोटाइप 1:2:1।"},"marks":[{"x":32.1,"y":18.8,"en":"Parents (P)","hi":"जनक"},{"x":14.2,"y":47.6,"en":"F1: all tall (Tt)","hi":"F1 पीढ़ी"},{"x":65,"y":32.8,"en":"Gametes T and t","hi":"युग्मक"},{"x":86,"y":49.4,"en":"F2: 3 tall : 1 dwarf","hi":"F2 पीढ़ी"}],"src":"ch8/mendel#4"}],"class9/biology/cell_membrane":[{"id":"c1","img":"conditions/class9_biology_cell_membrane__1.webp","title":{"en":"Semi-permeable membrane","hi":"अर्धपारगम्य झिल्ली"},"desc":{"en":"Now the membrane lets water pass but not solute. Water movement through such a membrane is called osmosis.","hi":"अब झिल्ली जल को जाने देती है, विलेय को नहीं। ऐसी झिल्ली से जल के गमन को परासरण कहते हैं।"},"marks":[{"x":37.6,"y":24.9,"en":"Left chamber","hi":"बायाँ कक्ष"},{"x":62.4,"y":24.9,"en":"Right chamber","hi":"दायाँ कक्ष"},{"x":50,"y":77.8,"en":"Semi-permeable membrane","hi":"अर्ध-पारगम्य झिल्ली"},{"x":34,"y":66.9,"en":"Water molecule","hi":"जल अणु"},{"x":32.3,"y":46.2,"en":"Solute particle","hi":"विलेय कण"}],"src":"ix1/osmosis#2"},{"id":"c2","img":"conditions/class9_biology_cell_membrane__2.webp","title":{"en":"Osmosis: water moves in","hi":"परासरण: जल अंदर आता है"},"desc":{"en":"Add solute on the left: water moves from the dilute (right) side to the concentrated (left) side, so the left level rises.","hi":"बाईं ओर विलेय डालिए: जल तनु (दाएँ) से सांद्र (बाएँ) की ओर जाता है, बाईं ओर स्तर बढ़ता है।"},"marks":[{"x":37.6,"y":24.9,"en":"Left chamber","hi":"बायाँ कक्ष"},{"x":62.4,"y":24.9,"en":"Right chamber","hi":"दायाँ कक्ष"},{"x":50,"y":77.8,"en":"Semi-permeable membrane","hi":"अर्ध-पारगम्य झिल्ली"},{"x":61.9,"y":51.1,"en":"Water molecule","hi":"जल अणु"},{"x":36.2,"y":56.4,"en":"Solute particle","hi":"विलेय कण"}],"src":"ix1/osmosis#3"},{"id":"c3","img":"conditions/class9_biology_cell_membrane__3.webp","title":{"en":"Balance it","hi":"संतुलन कीजिए"},"desc":{"en":"Add solute on the right too. When both sides have equal concentration (isotonic) there is no net movement of water.","hi":"दाईं ओर भी विलेय डालिए। जब दोनों ओर सांद्रता बराबर (समपरासरी) हो तो जल का कुल गमन नहीं होता।"},"marks":[{"x":37.6,"y":24.9,"en":"Left chamber","hi":"बायाँ कक्ष"},{"x":62.4,"y":24.9,"en":"Right chamber","hi":"दायाँ कक्ष"},{"x":50,"y":77.8,"en":"Semi-permeable membrane","hi":"अर्ध-पारगम्य झिल्ली"},{"x":54.9,"y":45.4,"en":"Water molecule","hi":"जल अणु"},{"x":35.9,"y":57.7,"en":"Solute particle","hi":"विलेय कण"}],"src":"ix1/osmosis#4"},{"id":"c4","img":"conditions/class9_biology_cell_membrane__4.webp","title":{"en":"In living cells","hi":"जीवित कोशिकाओं में"},"desc":{"en":"In a hypotonic solution a cell swells, in a hypertonic one it shrinks (plasmolysis in plants), in an isotonic one it stays the same. Raisins swell in water by osmosis.","hi":"अल्पपरासरी विलयन में कोशिका फूलती है, अतिपरासरी में सिकुड़ती है (पादपों में प्लाज़्मोलिसिस), समपरासरी में वैसी रहती है। किशमिश जल में परासरण से फूलती है।"},"marks":[{"x":37.6,"y":24.9,"en":"Left chamber","hi":"बायाँ कक्ष"},{"x":62.4,"y":24.9,"en":"Right chamber","hi":"दायाँ कक्ष"},{"x":50,"y":77.8,"en":"Semi-permeable membrane","hi":"अर्ध-पारगम्य झिल्ली"},{"x":42.1,"y":46.1,"en":"Water molecule","hi":"जल अणु"},{"x":35.8,"y":41.2,"en":"Solute particle","hi":"विलेय कण"}],"src":"ix1/osmosis#5"}],"class10/biology/cell_cycle_division":[{"id":"c1","img":"conditions/class10_biology_cell_cycle_division__1.webp","title":{"en":"Interphase: getting ready","hi":"अंतरावस्था: तैयारी"},"desc":{"en":"Before dividing the cell grows and copies its DNA (S phase), so every chromosome now has two identical sister chromatids. The chromosomes are long, thin threads (chromatin) inside the nucleus.","hi":"विभाजन से पहले कोशिका बढ़ती है और अपना DNA दोहराती है (S-प्रावस्था), इसलिए हर गुणसूत्र में दो समान सहोदर क्रोमैटिड हैं; गुणसूत्र केंद्रक में लंबे पतले धागे (क्रोमैटिन) हैं।"},"marks":[{"x":61,"y":27,"en":"Nucleus (intact)","hi":"केंद्रक (साबुत)"},{"x":41.5,"y":33.9,"en":"Chromatin: long thin threads","hi":"क्रोमैटिन: लंबे पतले धागे"},{"x":54.2,"y":10.9,"en":"Centrioles duplicated","hi":"तारककाय द्विगुणित"},{"x":55.9,"y":42.3,"en":"2 sister chromatids","hi":"2 सहोदर क्रोमैटिड"}],"src":"ix1/division3d#0"},{"id":"c2","img":"conditions/class10_biology_cell_cycle_division__2.webp","title":{"en":"Mitosis · Prophase","hi":"समसूत्री · पूर्वावस्था"},"desc":{"en":"The chromosomes coil up and become short and thick — visible X shapes. The nuclear envelope and nucleolus disappear; the centrioles move to the two poles and spindle fibres start to form.","hi":"गुणसूत्र कुंडलित होकर छोटे व मोटे (X आकार) हो जाते हैं; केंद्रक आवरण व केंद्रिका लुप्त होते हैं; तारककाय दोनों ध्रुवों पर जाती हैं और तर्कु तंतु बनने लगते हैं।"},"marks":[{"x":54.2,"y":10.9,"en":"Centrioles duplicated","hi":"तारककाय द्विगुणित"},{"x":44.1,"y":33.1,"en":"Condensed chromosomes (X)","hi":"संघनित गुणसूत्र (X)"},{"x":62.3,"y":31.6,"en":"Envelope breaking down","hi":"आवरण टूटता हुआ"},{"x":54.2,"y":79.9,"en":"Centrioles move to poles","hi":"तारककाय ध्रुवों पर"}],"src":"ix1/division3d#1"},{"id":"c3","img":"conditions/class10_biology_cell_cycle_division__3.webp","title":{"en":"Mitosis · Metaphase","hi":"समसूत्री · मध्यावस्था"},"desc":{"en":"Spindle fibres line all the chromosomes up on the equator (metaphase plate), one chromatid facing each pole. This is the best stage to count and photograph chromosomes.","hi":"तर्कु तंतु सभी गुणसूत्रों को मध्य रेखा (मध्यावस्था पट्टिका) पर पंक्ति में लाते हैं, प्रत्येक की एक क्रोमैटिड प्रत्येक ध्रुव की ओर; गुणसूत्र गिनने व चित्र लेने का सर्वोत्तम चरण।"},"marks":[{"x":54.2,"y":79.9,"en":"Centrioles move to poles","hi":"तारककाय ध्रुवों पर"},{"x":63.6,"y":45.4,"en":"Equator: chromosomes line up","hi":"मध्य रेखा: गुणसूत्र पंक्ति में"},{"x":43.2,"y":25.5,"en":"Spindle fibres","hi":"तर्कु तंतु"}],"src":"ix1/division3d#2"},{"id":"c4","img":"conditions/class10_biology_cell_cycle_division__4.webp","title":{"en":"Mitosis · Anaphase","hi":"समसूत्री · पश्चावस्था"},"desc":{"en":"The centromeres split and the spindle shortens: the sister chromatids are pulled to opposite poles. Each pole now receives an identical, complete set of chromosomes.","hi":"सेंट्रोमियर टूटते हैं और तर्कु छोटा होता है: सहोदर क्रोमैटिड विपरीत ध्रुवों पर खिंच जाते हैं; प्रत्येक ध्रुव को गुणसूत्रों का एक समान, पूरा समूह मिलता है।"},"marks":[{"x":43.9,"y":26.7,"en":"Spindle fibres","hi":"तर्कु तंतु"},{"x":60.6,"y":26.7,"en":"Chromatids pulled apart","hi":"क्रोमैटिड अलग खिंचते"},{"x":38.6,"y":66.5,"en":"Poles: identical sets","hi":"ध्रुव: समान समूह"}],"src":"ix1/division3d#3"},{"id":"c5","img":"conditions/class10_biology_cell_cycle_division__5.webp","title":{"en":"Telophase and cytokinesis","hi":"अंत्यावस्था व कोशिकाद्रव्य-विभाजन"},"desc":{"en":"Nuclear envelopes re-form round each set, the chromosomes uncoil, and the cytoplasm pinches in two (cytokinesis). Result: 2 daughter cells, identical to each other and to the parent (2n = 4). Used for growth and repair.","hi":"प्रत्येक समूह के चारों ओर केंद्रक आवरण पुनः बनता है, गुणसूत्र खुलते हैं और कोशिकाद्रव्य बीच से दो भागों में बँटता है; परिणाम: 2 संतति कोशिकाएँ, परस्पर व जनक के समान (2n = 4); वृद्धि व मरम्मत हेतु।"},"marks":[{"x":60.2,"y":22.9,"en":"Daughter cell 1 (2n = 4)","hi":"संतति कोशिका 1 (2n = 4)"},{"x":60.2,"y":61.9,"en":"Daughter cell 2 (2n = 4)","hi":"संतति कोशिका 2 (2n = 4)"},{"x":39.8,"y":42.4,"en":"Nuclei re-form · chromosomes uncoil","hi":"केंद्रक पुनः बनते"}],"src":"ix1/division3d#4"},{"id":"c6","img":"conditions/class10_biology_cell_cycle_division__6.webp","title":{"en":"Meiosis I · Prophase I: pairing and crossing over","hi":"अर्धसूत्री-I · पूर्वावस्था-I: जोड़ी व विनिमय"},"desc":{"en":"Now a cell that will make gametes. Homologous chromosomes (red + blue) find each other and pair up as a tetrad. They swap pieces at crossing-over points (chiasmata) — new gene combinations.","hi":"अब ऐसी कोशिका जो युग्मक बनाएगी: समजात गुणसूत्र (लाल + नीला) एक-दूसरे को पहचानकर चतुष्क (टेट्राड) में जुड़ते हैं और किएज़्मा पर टुकड़े अदल-बदल करते हैं — नए जीन-संयोजन।"},"marks":[{"x":44.1,"y":27,"en":"Homologous pair (tetrad)","hi":"समजात जोड़ी (टेट्राड)"},{"x":44.1,"y":31.6,"en":"Crossing over (chiasma)","hi":"जीन विनिमय (किएज़्मा)"},{"x":61,"y":36.2,"en":"Maternal (red) · paternal (blue)","hi":"मातृक (लाल) · पैतृक (नीला)"}],"src":"ix1/division3d#5"},{"id":"c7","img":"conditions/class10_biology_cell_cycle_division__7.webp","title":{"en":"Meiosis I: homologues separate","hi":"अर्धसूत्री-I: समजात अलग होते हैं"},"desc":{"en":"The pairs line up on the equator and then the whole homologous chromosomes (not chromatids) are pulled apart. Two cells form, each with only 2 chromosomes (n = 2): the chromosome number is halved. The reduction division.","hi":"जोड़े मध्य रेखा पर आते हैं और फिर पूरे समजात गुणसूत्र (क्रोमैटिड नहीं) अलग खिंचते हैं; दो कोशिकाएँ बनती हैं जिनमें केवल 2 गुणसूत्र (n = 2) हैं: संख्या आधी — न्यूनीकरण विभाजन।"},"marks":[{"x":60.2,"y":40.8,"en":"Pairs on the equator","hi":"जोड़े मध्य रेखा पर"},{"x":57.8,"y":23.4,"en":"Whole homologues separate","hi":"समजात गुणसूत्र अलग"},{"x":39.2,"y":41.9,"en":"Two cells: n = 2 (halved)","hi":"दो कोशिकाएँ: n = 2 (आधी)"}],"src":"ix1/division3d#6"},{"id":"c8","img":"conditions/class10_biology_cell_cycle_division__8.webp","title":{"en":"Meiosis II: chromatids separate","hi":"अर्धसूत्री-II: क्रोमैटिड अलग होते हैं"},"desc":{"en":"Each cell divides again like mitosis: the sister chromatids split. Result: 4 genetically different haploid cells (n = 2) — the gametes (sperm or egg).","hi":"प्रत्येक कोशिका समसूत्री की तरह फिर बँटती है: सहोदर क्रोमैटिड अलग होते हैं; परिणाम: 4 आनुवंशिक रूप से भिन्न अगुणित कोशिकाएँ (n = 2) — युग्मक (शुक्राणु या अंडाणु)।"},"marks":[{"x":50,"y":14,"en":"Meiosis II: chromatids split","hi":"अर्धसूत्री-II: क्रोमैटिड टूटते"},{"x":50,"y":71.4,"en":"4 different haploid gametes","hi":"4 भिन्न अगुणित युग्मक"}],"src":"ix1/division3d#7"}],"class9/physics/sea_land_breeze":[{"id":"c1","img":"conditions/class9_physics_sea_land_breeze__1.webp","title":{"en":"Sea breeze (day)","hi":"समुद्री समीर (दिन)"},"desc":{"en":"By day land is warmer: air rises over land and cooler air flows from the sea to the land.","hi":"दिन में स्थल गरम: स्थल पर हवा उठती और ठंडी हवा समुद्र से स्थल की ओर बहती है।"},"marks":[{"x":25,"y":67.2,"en":"Sea (cooler by day)","hi":"समुद्र"},{"x":75,"y":67.2,"en":"Land (warmer by day)","hi":"स्थल"},{"x":73,"y":34.8,"en":"Warm air rises","hi":"गरम वायु ऊपर"},{"x":50,"y":61.2,"en":"Surface wind","hi":"पृष्ठ पवन"}],"src":"ix8/breeze#1"},{"id":"c2","img":"conditions/class9_physics_sea_land_breeze__2.webp","title":{"en":"Land breeze (night)","hi":"स्थलीय समीर (रात)"},"desc":{"en":"By night land cools faster: the flow reverses, from land to sea.","hi":"रात में स्थल जल्दी ठंडा: प्रवाह उलटता है — स्थल से समुद्र की ओर।"},"marks":[{"x":25,"y":67.2,"en":"Sea (cooler by day)","hi":"समुद्र"},{"x":75,"y":67.2,"en":"Land (warmer by day)","hi":"स्थल"},{"x":30.6,"y":34.8,"en":"Warm air rises","hi":"गरम वायु ऊपर"},{"x":50,"y":61.2,"en":"Surface wind","hi":"पृष्ठ पवन"}],"src":"ix8/breeze#2"},{"id":"c3","img":"conditions/class9_physics_sea_land_breeze__3.webp","title":{"en":"Mountain and valley","hi":"पर्वत व घाटी समीर"},"desc":{"en":"By day the slope warms and air flows up the valley; at night cold air drains down.","hi":"दिन में ढलान गरम और हवा घाटी से ऊपर; रात में ठंडी हवा नीचे उतरती है।"},"marks":[{"x":25,"y":67.2,"en":"Sea (cooler by day)","hi":"समुद्र"},{"x":75,"y":67.2,"en":"Land (warmer by day)","hi":"स्थल"},{"x":67,"y":34.8,"en":"Warm air rises","hi":"गरम वायु ऊपर"},{"x":50,"y":61.2,"en":"Surface wind","hi":"पृष्ठ पवन"},{"x":65.4,"y":49.8,"en":"Mountain slope","hi":"पर्वत ढाल"}],"src":"ix8/breeze#3"}],"class9/physics/differential_heating":[{"id":"c1","img":"conditions/class9_physics_differential_heating__1.webp","title":{"en":"Latitude","hi":"अक्षांश"},"desc":{"en":"Near the equator rays fall straight and heat a small area; near the poles they slant over a large area — less heat per unit area.","hi":"विषुवत् पर किरणें सीधी व छोटा क्षेत्र गरम; ध्रुवों पर तिरछी व बड़े क्षेत्र में — प्रति इकाई ऊष्मा कम।"},"marks":[{"x":3.2,"y":35,"en":"Sun","hi":"सूर्य"},{"x":29.5,"y":30.2,"en":"Parallel sunlight","hi":"समानांतर सूर्य-किरणें"},{"x":70.6,"y":29.8,"en":"Surface patch","hi":"सतह का भाग"},{"x":76.5,"y":51.5,"en":"Equator","hi":"भूमध्य रेखा"}],"src":"ix8/heating#1"},{"id":"c2","img":"conditions/class9_physics_differential_heating__2.webp","title":{"en":"Seasons","hi":"ऋतुएँ"},"desc":{"en":"Earth's axis is tilted 23.5°: in June the north gets direct rays (summer); in December the south does.","hi":"पृथ्वी का अक्ष 23.5° झुका है: जून में उत्तर में सीधी किरणें (गर्मी); दिसंबर में दक्षिण में।"},"marks":[{"x":3.2,"y":35,"en":"Sun","hi":"सूर्य"},{"x":29.5,"y":30.2,"en":"Parallel sunlight","hi":"समानांतर सूर्य-किरणें"},{"x":65.9,"y":24,"en":"Surface patch","hi":"सतह का भाग"},{"x":76.5,"y":51.5,"en":"Equator","hi":"भूमध्य रेखा"}],"src":"ix8/heating#2"},{"id":"c3","img":"conditions/class9_physics_differential_heating__3.webp","title":{"en":"Albedo of surfaces","hi":"सतहों का एल्बीडो"},"desc":{"en":"Snow reflects most light (high albedo, stays cold); ocean and forest absorb it (low albedo).","hi":"बर्फ़ अधिक प्रकाश लौटाती है (उच्च एल्बीडो, ठंडी); सागर व वन सोखते हैं (निम्न एल्बीडो)।"},"marks":[{"x":3.2,"y":35,"en":"Sun","hi":"सूर्य"},{"x":29.5,"y":30.2,"en":"Parallel sunlight","hi":"समानांतर सूर्य-किरणें"},{"x":65.9,"y":24,"en":"Surface patch","hi":"सतह का भाग"},{"x":76.5,"y":51.5,"en":"Equator","hi":"भूमध्य रेखा"}],"src":"ix8/heating#3"}],"class9/physics/motion":[{"id":"c1","img":"conditions/class9_physics_motion__1.webp","title":{"en":"Uniform velocity","hi":"एकसमान वेग"},"desc":{"en":"With a = 0 the v–t graph is horizontal and the s–t graph is a straight line.","hi":"a = 0 पर v–t क्षैतिज और s–t सरल रेखा।"},"marks":[{"x":45.4,"y":72.2,"en":"Car (object)","hi":"कार"},{"x":21.8,"y":8.5,"en":"Position–time","hi":"स्थिति–समय"},{"x":50,"y":8.5,"en":"Velocity–time (area = displacement)","hi":"वेग–समय"},{"x":78.2,"y":8.5,"en":"Acceleration–time","hi":"त्वरण–समय"}],"src":"ix9/line#1"},{"id":"c2","img":"conditions/class9_physics_motion__2.webp","title":{"en":"Uniform acceleration","hi":"एकसमान त्वरण"},"desc":{"en":"Add a: v–t becomes a sloping line (slope = a) and s–t a parabola.","hi":"a बढ़ाइए: v–t ढलानदार (ढाल = a) और s–t परवलय।"},"marks":[{"x":88.9,"y":72.2,"en":"Car (object)","hi":"कार"},{"x":21.8,"y":8.5,"en":"Position–time","hi":"स्थिति–समय"},{"x":50,"y":8.5,"en":"Velocity–time (area = displacement)","hi":"वेग–समय"},{"x":78.2,"y":8.5,"en":"Acceleration–time","hi":"त्वरण–समय"}],"src":"ix9/line#2"},{"id":"c3","img":"conditions/class9_physics_motion__3.webp","title":{"en":"Negative acceleration","hi":"ऋणात्मक त्वरण"},"desc":{"en":"Retardation: velocity decreases, the car slows to rest.","hi":"मंदन: वेग घटता है और गाड़ी रुकती है।"},"marks":[{"x":46.1,"y":72.2,"en":"Car (object)","hi":"कार"},{"x":21.8,"y":8.5,"en":"Position–time","hi":"स्थिति–समय"},{"x":50,"y":8.5,"en":"Velocity–time (area = displacement)","hi":"वेग–समय"},{"x":78.2,"y":8.5,"en":"Acceleration–time","hi":"त्वरण–समय"}],"src":"ix9/line#3"}],"class9/physics/sound":[{"id":"c1","img":"conditions/class9_physics_sound__1.webp","title":{"en":"Frequency and amplitude","hi":"आवृत्ति व आयाम"},"desc":{"en":"Higher frequency means more waves per second (higher pitch); larger amplitude means louder.","hi":"अधिक आवृत्ति = प्रति सेकंड अधिक तरंगें (ऊँचा तारत्व); अधिक आयाम = प्रबल।"},"marks":[{"x":17.4,"y":49.1,"en":"Vibrating source (speaker)","hi":"कंपित स्रोत"},{"x":35.6,"y":50,"en":"Compression (dense)","hi":"संपीडन"},{"x":50,"y":50,"en":"Rarefaction (spread out)","hi":"विरलन"},{"x":65.3,"y":49.1,"en":"Wavelength λ","hi":"तरंगदैर्ध्य"},{"x":35.8,"y":17.9,"en":"Displacement vs distance","hi":"विस्थापन–दूरी"},{"x":64.2,"y":17.9,"en":"Displacement vs time (one point)","hi":"विस्थापन–समय"}],"src":"ix12/wave#1"},{"id":"c2","img":"conditions/class9_physics_sound__2.webp","title":{"en":"Different media","hi":"भिन्न माध्यम"},"desc":{"en":"Sound is faster in solids than liquids and gases: air 343 m/s, water ≈1480, steel ≈5000.","hi":"ध्वनि ठोस में द्रव व गैस से तेज़: वायु 343 m/s, जल ≈1480, इस्पात ≈5000।"},"marks":[{"x":17.4,"y":49.1,"en":"Vibrating source (speaker)","hi":"कंपित स्रोत"},{"x":35.6,"y":50,"en":"Compression (dense)","hi":"संपीडन"},{"x":50,"y":50,"en":"Rarefaction (spread out)","hi":"विरलन"},{"x":65.3,"y":49.1,"en":"Wavelength λ","hi":"तरंगदैर्ध्य"},{"x":35.8,"y":17.9,"en":"Displacement vs distance","hi":"विस्थापन–दूरी"},{"x":64.2,"y":17.9,"en":"Displacement vs time (one point)","hi":"विस्थापन–समय"}],"src":"ix12/wave#2"},{"id":"c3","img":"conditions/class9_physics_sound__3.webp","title":{"en":"No medium, no sound","hi":"माध्यम के बिना ध्वनि नहीं"},"desc":{"en":"In a vacuum there is nothing to compress: no sound.","hi":"निर्वात में संपीड़ित करने को कुछ नहीं — ध्वनि नहीं।"},"marks":[{"x":17.4,"y":49.1,"en":"Vibrating source (speaker)","hi":"कंपित स्रोत"},{"x":35.6,"y":50,"en":"Compression (dense)","hi":"संपीडन"},{"x":50,"y":50,"en":"Rarefaction (spread out)","hi":"विरलन"},{"x":65.3,"y":49.1,"en":"Wavelength λ","hi":"तरंगदैर्ध्य"},{"x":35.8,"y":17.9,"en":"Displacement vs distance","hi":"विस्थापन–दूरी"},{"x":64.2,"y":17.9,"en":"Displacement vs time (one point)","hi":"विस्थापन–समय"}],"src":"ix12/wave#3"}],"class9/chemistry/tyndall":[{"id":"c1","img":"conditions/class9_chemistry_tyndall__1.webp","title":{"en":"Tyndall effect","hi":"टिंडल प्रभाव"},"desc":{"en":"Shine a torch: the colloid and suspension scatter light and show the beam; the solution does not.","hi":"टॉर्च चमकाइए: कोलॉइड व निलंबन प्रकाश बिखेरकर किरण दिखाते हैं; विलयन नहीं।"},"marks":[{"x":25.8,"y":33.5,"en":"Solution (homogeneous)","hi":"विलयन (समांगी)"},{"x":50,"y":33.5,"en":"Colloid","hi":"कोलॉइड"},{"x":74.2,"y":33.5,"en":"Suspension (heterogeneous)","hi":"निलंबन (विषमांगी)"},{"x":13.7,"y":48.8,"en":"Torch","hi":"टॉर्च"}],"src":"ix5/types#1"},{"id":"c2","img":"conditions/class9_chemistry_tyndall__2.webp","title":{"en":"Filtration","hi":"निस्यंदन"},"desc":{"en":"Pour each through filter paper: the suspension leaves a residue; solution and colloid pass through.","hi":"प्रत्येक को छन्ने से डालिए: निलंबन अवशेष छोड़ता है; विलयन व कोलॉइड निकल जाते हैं।"},"marks":[{"x":25.8,"y":33.5,"en":"Solution (homogeneous)","hi":"विलयन (समांगी)"},{"x":50,"y":33.5,"en":"Colloid","hi":"कोलॉइड"},{"x":74.2,"y":33.5,"en":"Suspension (heterogeneous)","hi":"निलंबन (विषमांगी)"},{"x":13.7,"y":48.8,"en":"Torch","hi":"टॉर्च"},{"x":74.2,"y":32.9,"en":"Residue on filter paper","hi":"छन्नी पर अवशेष"}],"src":"ix5/types#2"},{"id":"c3","img":"conditions/class9_chemistry_tyndall__3.webp","title":{"en":"Wait one hour","hi":"एक घंटा प्रतीक्षा"},"desc":{"en":"The suspension settles into layers; solution and colloid stay uniform and stable.","hi":"निलंबन परतों में बैठ जाता है; विलयन व कोलॉइड एकसमान, स्थिर रहते हैं।"},"marks":[{"x":25.8,"y":33.5,"en":"Solution (homogeneous)","hi":"विलयन (समांगी)"},{"x":50,"y":33.5,"en":"Colloid","hi":"कोलॉइड"},{"x":74.2,"y":33.5,"en":"Suspension (heterogeneous)","hi":"निलंबन (विषमांगी)"},{"x":13.7,"y":48.8,"en":"Torch","hi":"टॉर्च"},{"x":74.2,"y":32.9,"en":"Residue on filter paper","hi":"छन्नी पर अवशेष"}],"src":"ix5/types#3"}],"class9/physics/newton_laws":[{"id":"c1","img":"conditions/class9_physics_newton_laws__1.webp","title":{"en":"Friction","hi":"घर्षण"},"desc":{"en":"Push the block: until F beats static friction it does not move (balanced forces). Try ice, wood and a rough surface.","hi":"ब्लॉक को धकेलिए: जब तक F स्थैतिक घर्षण से कम है, वह नहीं हिलता (संतुलित बल); बर्फ़, लकड़ी, खुरदरी सतह आज़माइए।"},"marks":[{"x":50,"y":42.8,"en":"Block","hi":"गुटका"}],"src":"ix10/forces#1"},{"id":"c2","img":"conditions/class9_physics_newton_laws__2.webp","title":{"en":"F = ma","hi":"F = ma"},"desc":{"en":"For the same force a larger mass gives a smaller acceleration.","hi":"समान बल पर अधिक द्रव्यमान = कम त्वरण।"},"marks":[{"x":50,"y":42.1,"en":"Block","hi":"गुटका"}],"src":"ix10/forces#2"},{"id":"c3","img":"conditions/class9_physics_newton_laws__3.webp","title":{"en":"Action and reaction","hi":"क्रिया-प्रतिक्रिया"},"desc":{"en":"Two carts pushed apart by a spring move in opposite directions with equal and opposite forces.","hi":"स्प्रिंग से धकेली दो गाड़ियाँ विपरीत दिशा में, समान व विपरीत बलों से चलती हैं।"},"marks":[{"x":17.8,"y":48,"en":"Cart A","hi":"गाड़ी A"},{"x":82.9,"y":48,"en":"Cart B","hi":"गाड़ी B"}],"src":"ix10/forces#3"},{"id":"c4","img":"conditions/class9_physics_newton_laws__4.webp","title":{"en":"Inertia","hi":"जड़त्व"},"desc":{"en":"A body at rest stays at rest, and a moving body keeps moving, unless a net force acts: seat-belts, shaking dust off a carpet.","hi":"विराम की वस्तु विराम में और गतिमान गति में रहती है जब तक असंतुलित बल न लगे: सीट-बेल्ट, कालीन झाड़ना।"},"marks":[{"x":50,"y":42.1,"en":"Block","hi":"गुटका"},{"x":17.8,"y":48,"en":"Cart A","hi":"गाड़ी A"},{"x":82.9,"y":48,"en":"Cart B","hi":"गाड़ी B"},{"x":45.5,"y":48,"en":"Cart","hi":"गाड़ी"},{"x":45.5,"y":45.9,"en":"Ball (inertia)","hi":"गेंद (जड़त्व)"}],"src":"ix10/forces#4"}],"class10/physics/scattering_light":[{"id":"c1","img":"conditions/class10_physics_scattering_light__1.webp","title":{"en":"Why is the sky blue?","hi":"आकाश नीला क्यों है?"},"desc":{"en":"Sunlight is white. Air molecules are much smaller than the wavelength of light and scatter short wavelengths (blue) far more than long ones (red) — Rayleigh scattering.","hi":"सूर्य-प्रकाश श्वेत है; वायु के अणु तरंगदैर्ध्य से बहुत छोटे हैं और छोटे तरंगदैर्ध्य (नीला) को लाल से अधिक बिखेरते हैं — रैले प्रकीर्णन।"},"marks":[{"x":35.4,"y":72.9,"en":"Observer","hi":"प्रेक्षक"},{"x":14.1,"y":56.1,"en":"Atmosphere (air molecules)","hi":"वायुमंडल"}],"src":"ch10/scatter#0"},{"id":"c2","img":"conditions/class10_physics_scattering_light__2.webp","title":{"en":"Sunset is red","hi":"सूर्यास्त लाल क्यों"},"desc":{"en":"At sunset light passes through a much thicker layer of air; most blue is scattered away and mainly red reaches your eye.","hi":"सूर्यास्त पर प्रकाश वायु की बहुत मोटी परत से आता है; अधिकांश नीला बिखर जाता है और मुख्यतः लाल पहुँचता है।"},"marks":[{"x":35.4,"y":72.9,"en":"Observer","hi":"प्रेक्षक"},{"x":80.5,"y":62.7,"en":"Sun","hi":"सूर्य"},{"x":14.1,"y":56.1,"en":"Atmosphere (air molecules)","hi":"वायुमंडल"}],"src":"ch10/scatter#1"},{"id":"c3","img":"conditions/class10_physics_scattering_light__3.webp","title":{"en":"No atmosphere","hi":"बिना वायुमंडल"},"desc":{"en":"Astronauts see a black sky even in daytime: no air, no scattering.","hi":"अंतरिक्ष यात्रियों को दिन में भी काला आकाश दिखता है — हवा नहीं, प्रकीर्णन नहीं।"},"marks":[{"x":35.4,"y":72.9,"en":"Observer","hi":"प्रेक्षक"},{"x":71.8,"y":21.5,"en":"Sun","hi":"सूर्य"}],"src":"ch10/scatter#2"}],"class10/biology/nervous_system":[{"id":"c1","img":"conditions/class10_biology_nervous_system__1.webp","title":{"en":"Dendrites receive, the axon sends","hi":"द्रुमिकाएँ लेती हैं, एक्सॉन भेजता है"},"desc":{"en":"Information enters through the dendrites, passes through the cell body and leaves along the axon: dendrite → cell body → axon → terminal. The impulse is electrical here.","hi":"सूचना द्रुमिकाओं से आती है, कोशिका काय से गुज़रती है और एक्सॉन से बाहर जाती है: द्रुमिका → कोशिका काय → एक्सॉन → अंत। यहाँ आवेग विद्युत है।"},"marks":[{"x":50,"y":33.5,"en":"Cell body (soma)","hi":"कोशिका काय"},{"x":50.2,"y":52,"en":"Nucleus","hi":"केंद्रक"},{"x":36.7,"y":28.3,"en":"Dendrites (receive)","hi":"द्रुमिकाएँ (ग्रहण)"},{"x":94.7,"y":46.6,"en":"Axon (carries away)","hi":"एक्सॉन (दूर ले जाता)"},{"x":81.1,"y":27.6,"en":"Impulse direction →","hi":"आवेग की दिशा →"}],"src":"ch6/neuron3d#1"},{"id":"c2","img":"conditions/class10_biology_nervous_system__2.webp","title":{"en":"Myelin and the jumping impulse","hi":"माइलिन व कूदता आवेग"},"desc":{"en":"Myelin insulates the axon. The impulse jumps from one node of Ranvier to the next (saltatory conduction), which is much faster than creeping along a bare fibre.","hi":"माइलिन एक्सॉन को ढकता है; आवेग एक रैन्वियर पर्व से अगले पर कूदता है (लवणीय चालन), जो नंगे तंतु पर रेंगने से कहीं तेज़ है।"},"marks":[{"x":50,"y":47.7,"en":"Axon (carries away)","hi":"एक्सॉन (दूर ले जाता)"},{"x":44.2,"y":44.3,"en":"Myelin sheath","hi":"माइलिन आवरण"},{"x":41.7,"y":47.7,"en":"Node of Ranvier","hi":"रैन्वियर पर्व"},{"x":36.8,"y":31.3,"en":"Impulse direction →","hi":"आवेग की दिशा →"}],"src":"ch6/neuron3d#2"},{"id":"c3","img":"conditions/class10_biology_nervous_system__3.webp","title":{"en":"What happens at a node","hi":"पर्व पर क्या होता है"},"desc":{"en":"At a node, sodium ions rush IN and the membrane flips from −70 mV to about +30 mV; then potassium ions flow OUT and it resets. This wave of change is the action potential.","hi":"पर्व पर Na⁺ आयन तेज़ी से अंदर आते हैं और झिल्ली −70 mV से लगभग +30 mV हो जाती है; फिर K⁺ बाहर बहते हैं और पुनः स्थापित होती है — यही क्रिया-विभव है।"},"marks":[{"x":50,"y":44.9,"en":"Node of Ranvier","hi":"रैन्वियर पर्व"},{"x":45.5,"y":26.3,"en":"Na⁺ in (depolarise)","hi":"Na⁺ अंदर (विध्रुवण)"},{"x":54.1,"y":71.5,"en":"K⁺ out (repolarise)","hi":"K⁺ बाहर (पुनर्ध्रुवण)"},{"x":50,"y":9.1,"en":"Action potential −70 → +30 mV","hi":"क्रिया-विभव −70 → +30 mV"}],"src":"ch6/neuron3d#3"},{"id":"c4","img":"conditions/class10_biology_nervous_system__4.webp","title":{"en":"The synapse: a chemical bridge","hi":"सिनैप्स: रासायनिक पुल"},"desc":{"en":"The impulse reaches the knob; vesicles release neurotransmitter into the 20 nm gap; it binds receptors on the next cell and starts a new impulse. The signal goes one way only.","hi":"आवेग बटन तक पहुँचता है; पुटिकाएँ 20 nm दरार में न्यूरोट्रांसमीटर छोड़ती हैं; वह अगली कोशिका के ग्राहियों से जुड़कर नया आवेग शुरू करता है; संकेत केवल एक दिशा में जाता है।"},"marks":[{"x":29.6,"y":21.6,"en":"Pre-synaptic knob","hi":"पूर्व-सिनैप्टिक बटन"},{"x":37.1,"y":47,"en":"Vesicles with neurotransmitter","hi":"पुटिकाएँ (न्यूरोट्रांसमीटर)"},{"x":53.7,"y":21.6,"en":"Synaptic cleft (~20 nm)","hi":"सिनैप्टिक दरार"},{"x":58.9,"y":81.6,"en":"Post-synaptic membrane","hi":"पश्च-सिनैप्टिक झिल्ली"},{"x":55.7,"y":40.6,"en":"Receptors","hi":"ग्राही"},{"x":53.5,"y":57,"en":"Neurotransmitter crossing","hi":"न्यूरोट्रांसमीटर पार जाता"}],"src":"ch6/neuron3d#4"},{"id":"c5","img":"conditions/class10_biology_nervous_system__5.webp","title":{"en":"Reflex arc: the fast shortcut","hi":"प्रतिवर्त चाप: तेज़ छोटा रास्ता"},"desc":{"en":"Touch something hot: receptor → sensory neuron → spinal cord (relay) → motor neuron → muscle. The hand moves away before the brain even feels the pain.","hi":"गर्म वस्तु छूते ही: ग्राही → संवेदी तंत्रिका → मेरुरज्जु (रिले) → प्रेरक तंत्रिका → पेशी; मस्तिष्क को दर्द महसूस होने से पहले ही हाथ हट जाता है।"},"marks":[{"x":21.2,"y":45.5,"en":"Receptor (skin) — hot!","hi":"ग्राही (त्वचा) — गर्म!"},{"x":33,"y":44.4,"en":"Sensory neuron →","hi":"संवेदी तंत्रिका →"},{"x":50,"y":39,"en":"Spinal cord (relay neuron)","hi":"मेरुरज्जु (रिले तंत्रिका)"},{"x":66.5,"y":44.3,"en":"→ Motor neuron","hi":"→ प्रेरक तंत्रिका"},{"x":81.1,"y":42.9,"en":"Effector: muscle contracts","hi":"प्रभावक: पेशी सिकुड़ती"}],"src":"ch6/neuron3d#5"}],"class9/biology/skeleton_joint":[{"id":"c1","img":"conditions/class9_biology_skeleton_joint__1.webp","title":{"en":"The elbow: a hinge joint","hi":"कोहनी: कब्ज़ा संधि"},"desc":{"en":"At a hinge joint movement is in one plane only — like a door. A capsule and ligaments hold the bones together.","hi":"कब्ज़ा संधि में गति एक ही तल में होती है — दरवाज़े की तरह। कैप्सूल व स्नायु अस्थियों को जोड़े रखते हैं।"},"marks":[{"x":53.2,"y":68,"en":"Radius","hi":"रेडियस"},{"x":51.8,"y":65.9,"en":"Ulna","hi":"अल्ना"},{"x":52.6,"y":45.3,"en":"Joint capsule","hi":"संधि कैप्सूल"},{"x":53.5,"y":49.8,"en":"Ligament","hi":"स्नायु"},{"x":50.4,"y":49.5,"en":"Hinge joint (elbow)","hi":"कब्ज़ा संधि (कोहनी)"}],"src":"ix2/joint3d#1","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c2","img":"conditions/class9_biology_skeleton_joint__2.webp","title":{"en":"Muscles work in pairs","hi":"पेशियाँ जोड़ी में कार्य करती हैं"},"desc":{"en":"Biceps (front) and triceps (back) are an antagonistic pair: when one contracts the other relaxes. Muscles can only pull, never push.","hi":"द्विशिर (आगे) व त्रिशिर (पीछे) विरोधी जोड़ी हैं: एक सिकुड़ती है तो दूसरी शिथिल होती है। पेशियाँ केवल खींच सकती हैं, धकेल नहीं।"},"marks":[{"x":49.8,"y":38.9,"en":"Humerus","hi":"ह्यूमरस"},{"x":49.2,"y":40.4,"en":"Biceps (flexor)","hi":"द्विशिर (आकुंचक)"},{"x":51.9,"y":41,"en":"Triceps (extensor)","hi":"त्रिशिर (प्रसारक)"}],"src":"ix2/joint3d#2","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c3","img":"conditions/class9_biology_skeleton_joint__3.webp","title":{"en":"Bending the arm (flexion)","hi":"भुजा मोड़ना (आकुंचन)"},"desc":{"en":"The biceps contracts and shortens, pulling the forearm up. The triceps relaxes.","hi":"द्विशिर सिकुड़कर छोटी होती है और अग्रबाहु को ऊपर खींचती है; त्रिशिर शिथिल रहती है।"},"marks":[{"x":49.2,"y":38.5,"en":"Biceps (flexor)","hi":"द्विशिर (आकुंचक)"},{"x":49.8,"y":37.7,"en":"Hinge joint (elbow)","hi":"कब्ज़ा संधि (कोहनी)"}],"src":"ix2/joint3d#3","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"},{"id":"c4","img":"conditions/class9_biology_skeleton_joint__4.webp","title":{"en":"Straightening the arm (extension)","hi":"भुजा सीधी करना (प्रसारण)"},"desc":{"en":"The triceps contracts and pulls the forearm back down; the biceps relaxes.","hi":"त्रिशिर सिकुड़कर अग्रबाहु को नीचे खींचती है; द्विशिर शिथिल होती है।"},"marks":[{"x":51.9,"y":39.8,"en":"Triceps (extensor)","hi":"त्रिशिर (प्रसारक)"},{"x":49.8,"y":48.8,"en":"Hinge joint (elbow)","hi":"कब्ज़ा संधि (कोहनी)"}],"src":"ix2/joint3d#4","credit":"Anatomy © BodyParts3D (DBCLS, CC BY-SA 2.1 JP) · Z-Anatomy (CC BY-SA 4.0), simplified render — shared under CC BY-SA 4.0"}]};
